/* Spanish translation of the CompTIA A+ Core 1 practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("a-plus-core1", {
  "ap1": ["El touchpad de una laptop empezó a abombarse hacia arriba y la tapa ya no cierra al ras. ¿Qué debe hacer el técnico PRIMERO?", ["Apagarla, desconectarla y retirar la batería hinchada", "Descargar y recargar completamente la batería para recalibrarla", "Actualizar el driver del touchpad y el firmware del sistema", "Presionar la carcasa para cerrarla y volver a asentar el cable del touchpad"], "Un touchpad abombado suele indicar una batería de iones de litio hinchada, lo cual es un riesgo de incendio; hay que dejar de cargarla y reemplazarla. Recalibrar una batería hinchada mantiene en servicio una pieza peligrosa.", [null, "Hacer ciclos de carga a una batería de iones de litio hinchada mantiene en servicio una celda dañada y propensa a incendiarse, y puede empeorar la hinchazón.", "Los drivers y el firmware no pueden corregir un abultamiento físico; el touchpad está siendo empujado hacia arriba por la batería que tiene debajo.", "Presionar una batería de iones de litio hinchada puede perforarla e iniciar un incendio, y el cable no es la causa del abultamiento."]],
  "ap2": ["Un técnico abre una laptop ultradelgada para agregar memoria, pero no encuentra ranuras SODIMM. ¿Cuál es la explicación MÁS probable?", ["Las ranuras SODIMM están detrás del panel de la pantalla", "Las ranuras permanecen ocultas hasta que se habilitan en UEFI", "La memoria está soldada a la placa del sistema", "La laptop usa DIMM de tamaño completo debajo del teclado"], "Muchas laptops delgadas usan memoria soldada a la placa base, por lo que no se puede ampliar. La configuración del firmware nunca oculta ranuras físicas.", ["La memoria de una laptop nunca se monta detrás del panel de la pantalla; las ranuras, cuando existen, están en la placa del sistema bajo la tapa inferior o el teclado.", "UEFI puede deshabilitar funciones, pero no puede ocultar conectores físicos; si no se ve ninguna ranura en la placa, no existe.", null, "Las laptops usan SODIMM o memoria soldada, no DIMM de escritorio de tamaño completo, que no cabrían en un chasis delgado."]],
  "ap3": ["Una laptop tiene una ranura M.2 compatible con PCIe. ¿Qué unidad de reemplazo ofrece el MEJOR rendimiento de almacenamiento?", ["Un SSD M.2 SATA", "Un disco duro de 2.5 pulgadas a 7200 RPM", "Un SSD SATA de 2.5 pulgadas en un adaptador", "Un SSD M.2 NVMe"], "Las unidades NVMe usan carriles PCIe y son mucho más rápidas que cualquier unidad limitada por la interfaz SATA, incluidos los SSD M.2 SATA que se ven parecidos.", ["Un SSD M.2 SATA usa el formato M.2, pero sigue limitado a los aproximadamente 600 MB/s de la interfaz SATA, muy por debajo de las velocidades PCIe NVMe.", "Un disco duro mecánico de 7200 RPM es por mucho la opción más lenta, con tiempos de búsqueda mecánicos, y ni siquiera usaría la ranura M.2.", "Un adaptador no cambia la interfaz; un SSD SATA de 2.5 pulgadas sigue limitado por el ancho de banda de SATA.", null]],
  "ap4": ["Después de reemplazar la tarjeta Wi-Fi de una laptop, el usuario solo ve una red débil incluso junto al access point. ¿Qué se omitió MÁS probablemente?", ["La nueva tarjeta necesita una dirección IP estática", "El access point debe reiniciarse después de cambiar una tarjeta", "El SSID debe volver a ingresarse en la configuración de UEFI", "Los cables de antena no se volvieron a conectar a la tarjeta"], "Las antenas Wi-Fi de una laptop suelen pasar por el marco de la pantalla y se conectan a la tarjeta; sin ellas la tarjeta apenas recibe señal. La configuración IP no afecta la intensidad de la señal.", ["El direccionamiento IP ocurre después de la asociación y no influye en cuántas redes detecta la tarjeta ni en la intensidad de la señal.", "Cambiar la tarjeta de la laptop no requiere reiniciar el access point, y reiniciarlo no mejoraría la recepción de la laptop.", "Los SSID se ingresan en la configuración Wi-Fi del sistema operativo, no en UEFI, y hacerlo no corregiría la recepción débil.", null]],
  "ap5": ["Un usuario quiere emparejar un nuevo headset Bluetooth con un teléfono. El Bluetooth ya está activado. ¿Cuál es el siguiente paso?", ["Poner el headset en modo de emparejamiento", "Tocar el headset contra el área NFC del teléfono", "Conectar el headset al teléfono con USB-C", "Unir el headset a la misma red Wi-Fi"], "El emparejamiento requiere que el accesorio sea detectable; luego el usuario lo selecciona en el teléfono y confirma el PIN o la clave si se solicita. El Wi-Fi no interviene en el emparejamiento Bluetooth.", [null, "El emparejamiento por toque NFC solo funciona si ambos dispositivos lo admiten, y el headset igual tiene que ser detectable; no es el siguiente paso estándar.", "Un cable USB-C carga el headset o transporta audio por cable, pero no realiza el emparejamiento Bluetooth.", "El emparejamiento Bluetooth es un enlace directo entre dispositivos y no tiene nada que ver con unirse a una red Wi-Fi."]],
  "ap6": ["¿Qué tecnología inalámbrica permite que un teléfono realice un pago cuando se sostiene a pocos centímetros de una terminal?", ["Bluetooth", "Infrarrojo", "NFC", "Wi-Fi Direct"], "Near-field communication funciona solo a unos pocos centímetros, lo que la hace ideal para pagos por contacto (tap-to-pay). Bluetooth funciona a varios metros y no se usa para pagos sin contacto con tarjeta.", ["Bluetooth funciona a varios metros y requiere emparejamiento, así que no es lo que usan las terminales de pago sin contacto.", "El infrarrojo necesita línea de vista y se usa en controles remotos y enlaces de datos antiguos, no en los pagos modernos por contacto.", null, "Wi-Fi Direct conecta dispositivos punto a punto a decenas de metros y no se usa para pagos sin contacto con tarjeta."]],
  "ap7": ["Un empleado que viaja necesita internet en su laptop en un sitio sin Wi-Fi. El teléfono del empleado tiene un plan celular ilimitado. ¿Cuál es la solución más rápida?", ["Habilitar NFC en ambos dispositivos", "Emparejar la laptop y el teléfono para transferir archivos", "Habilitar los servicios de ubicación del teléfono", "Activar el hotspot móvil del teléfono"], "Un hotspot (tethering) comparte los datos celulares del teléfono con la laptop por Wi-Fi, USB o Bluetooth. Emparejar para transferir archivos no comparte una conexión a internet.", ["NFC solo intercambia pequeñas cantidades de datos a unos pocos centímetros y no puede compartir una conexión a internet.", "Emparejar para transferir archivos crea un enlace Bluetooth para archivos, pero no enruta los datos celulares del teléfono hacia la laptop.", "Los servicios de ubicación solo permiten que las apps conozcan la posición del teléfono; no dan acceso a la red a otro dispositivo.", null]],
  "ap8": ["Una empresa quiere enviar la configuración de correo a los teléfonos del personal, exigir bloqueo de pantalla y borrar remotamente un dispositivo perdido. ¿Qué debe implementar?", ["Una VPN site-to-site", "Mobile device management (MDM)", "Un portal cautivo en el Wi-Fi de invitados", "Un switch KVM en cada oficina"], "MDM inscribe los dispositivos para que TI pueda enviar configuraciones, aplicar políticas como códigos de acceso y borrar dispositivos perdidos. Una VPN solo protege el tráfico en tránsito.", ["Una VPN site-to-site conecta los routers de dos redes y no tiene capacidad para configurar, bloquear ni borrar teléfonos individuales.", null, "Un portal cautivo solo muestra una página de inicio de sesión o de términos antes de dar acceso al Wi-Fi de invitados; no puede administrar dispositivos.", "Un switch KVM comparte un teclado, video y mouse entre varias computadoras y no tiene nada que ver con teléfonos."]],
  "ap9": ["Un usuario quiere un solo cable desde su laptop para conectar dos monitores, Ethernet cableado, un teclado y la carga. ¿Qué debe recomendar el técnico?", ["Un switch KVM", "Un dock USB-C o Thunderbolt", "Un inyector PoE", "Un hub USB 2.0"], "Una docking station USB-C/Thunderbolt transporta video, datos, red y power delivery por un solo cable. Un KVM comparte un conjunto de periféricos entre varias computadoras.", ["Un switch KVM permite que un conjunto de periféricos controle varias computadoras; no proporciona Ethernet, carga ni varias pantallas por un solo cable.", null, "Un inyector PoE agrega energía a un cable Ethernet para dispositivos como cámaras y access points, no video, periféricos ni carga de laptop.", "Un hub USB 2.0 solo agrega puertos USB de baja velocidad; no puede manejar dos monitores ni entregar energía para cargar una laptop."]],
  "ap10": ["¿Qué componente del teléfono determina la ubicación a partir de satélites incluso cuando no hay señal celular ni Wi-Fi?", ["Receptor GPS", "Giroscopio", "Controlador NFC", "Digitalizador"], "El receptor GPS (GNSS) calcula la posición a partir de señales satelitales. Un giroscopio solo mide rotación y orientación.", [null, "Un giroscopio mide rotación y orientación, lo que ayuda con la rotación de pantalla y el movimiento, pero no puede determinar la ubicación.", "Un controlador NFC maneja comunicación de corto alcance por toque, como pagos, y no participa en el posicionamiento.", "El digitalizador es la capa táctil de la pantalla y no tiene nada que ver con la ubicación."]],
  "ap11": ["La pantalla de una tablet muestra una imagen nítida, pero los toques en el tercio inferior de la pantalla se ignoran. ¿Qué pieza MÁS probablemente debe reemplazarse?", ["El digitalizador", "La retroiluminación LCD", "El inversor de pantalla", "El procesador gráfico"], "El digitalizador es la capa táctil; si está dañado ignora los toques mientras la imagen sigue bien. Una falla de retroiluminación oscurecería la imagen, no bloquearía el toque.", [null, "La imagen es nítida y brillante, así que la retroiluminación funciona; una falla de retroiluminación oscurecería toda la imagen, no bloquearía el toque.", "Un inversor alimenta las antiguas retroiluminaciones CCFL y afecta el brillo, no la entrada táctil; las tablets modernas usan retroiluminación LED sin inversor.", "Una falla de la GPU distorsionaría o dejaría en negro la imagen, pero aquí la pantalla está bien y solo falla la entrada táctil."]],
  "ap12": ["Un diseñador gráfico quiere dibujar con sensibilidad a la presión en una laptop sin pantalla táctil. ¿Qué accesorio es adecuado?", ["Una webcam", "Una tableta de dibujo", "Un trackpoint", "Un escáner de códigos de barras"], "Una tableta de dibujo (tableta gráfica) con stylus permite dibujar con sensibilidad a la presión en cualquier laptop. Un trackpoint solo mueve el puntero.", ["Una webcam captura video para llamadas y no puede usarse como superficie de dibujo sensible a la presión.", null, "Un trackpoint es una pequeña palanca para mover el cursor; no ofrece entrada de lápiz ni sensibilidad a la presión.", "Un escáner de códigos de barras lee códigos impresos para inventario o ventas y no sirve para dibujar."]],
  "ap13": ["Una mesa de ayuda necesita conectarse a los escritorios Windows de los usuarios con Remote Desktop a través de un firewall interno. ¿Qué puerto debe estar abierto?", ["TCP 3389", "TCP 22", "TCP 445", "UDP 3390"], "RDP escucha en TCP 3389. El puerto 22 es SSH, que Windows Remote Desktop no usa.", [null, "TCP 22 es SSH, que se usa para acceso seguro por línea de comandos, no para el Remote Desktop Protocol de Windows.", "TCP 445 transporta el uso compartido de archivos e impresoras SMB, no sesiones de Remote Desktop.", "RDP usa el puerto 3389 (TCP y, opcionalmente, UDP 3389); 3390 no es el puerto de RDP."]],
  "ap14": ["Los usuarios pueden llegar a un sitio web por su dirección IP, pero no por su nombre. ¿El tráfico de qué puerto MÁS probablemente está bloqueado?", ["80", "25", "53", "110"], "La resolución de nombres usa DNS en el puerto 53 (UDP y TCP). El puerto 80 transporta HTTP, que aquí funciona porque el sitio carga por IP.", ["El puerto 80 es HTTP; claramente funciona porque el sitio carga cuando se accede por su dirección IP.", "El puerto 25 es SMTP para transferir correo entre servidores y no interviene en la resolución de nombres de sitios web.", null, "El puerto 110 es POP3 para descargar correo y no tiene relación con la búsqueda de nombres de host."]],
  "ap15": ["¿Qué afirmación describe MEJOR a UDP?", ["Sin conexión, sin garantía de entrega", "Orientado a conexión, con un three-way handshake", "Reenvía los segmentos perdidos y los reordena", "Se usa solo para tráfico web seguro"], "UDP envía datagramas sin handshake ni acuses de recibo, lo que es adecuado para consultas DNS, DHCP y streaming. El handshake y la retransmisión son propios de TCP.", [null, "La entrega orientada a conexión con three-way handshake describe a TCP, no a UDP.", "Retransmitir segmentos perdidos y ponerlos en orden son funciones de TCP; UDP deja eso a la aplicación si hace falta.", "El tráfico web seguro es HTTPS, que en su mayoría usa TCP 443; UDP transporta muchos tipos de tráfico, como DNS, DHCP y streaming."]],
  "ap16": ["Un técnico está solucionando problemas con recursos compartidos de Windows que no se abren en toda la oficina. ¿Qué puerto usa SMB directamente?", ["TCP 389", "TCP 445", "UDP 161", "TCP 143"], "El SMB moderno funciona directamente sobre TCP 445. El puerto 389 es LDAP, que se usa para consultas de directorio, no para compartir archivos.", ["TCP 389 es LDAP, que se usa para consultar servicios de directorio como Active Directory, no para transportar tráfico de recursos compartidos.", null, "UDP 161 es SNMP, que se usa para monitorear y administrar dispositivos de red, no para compartir archivos en Windows.", "TCP 143 es IMAP, que usan los clientes de correo para leer el correo en un servidor."]],
  "ap17": ["¿Qué protocolo y puerto usan los servidores de correo para enviar correo a otros servidores de correo?", ["IMAP en el puerto 143", "POP3 en el puerto 110", "SMTP en el puerto 25", "LDAP en el puerto 389"], "SMTP (puerto 25) transfiere correo entre servidores. IMAP y POP3 los usan los clientes para obtener el correo de su propio servidor.", ["IMAP en el 143 permite a los clientes de correo leer y administrar el correo almacenado en su propio servidor; no envía correo entre servidores.", "POP3 en el 110 permite a los clientes descargar el correo de su buzón; no se usa para la entrega entre servidores.", null, "LDAP en el 389 consulta servicios de directorio como libretas de direcciones; no transfiere correo."]],
  "ap18": ["Una oficina pequeña reemplaza un hub antiguo por un dispositivo que aprende direcciones MAC y reenvía las tramas solo al puerto de destino. ¿Qué se instaló?", ["Un repetidor", "Un módem", "Un switch", "Un patch panel"], "Un switch mantiene una tabla de direcciones MAC y reenvía las tramas solo a donde deben ir. Un hub o un repetidor envía cada trama por todos los puertos.", ["Un repetidor simplemente regenera la señal y la reenvía, sin conocer las direcciones MAC.", "Un módem convierte señales entre el medio del ISP (cable, DSL) y Ethernet; no reenvía tramas por dirección MAC.", null, "Un patch panel es un punto de terminación pasivo para tendidos de cable y no toma decisiones de reenvío."]],
  "ap19": ["Hay que montar nuevas cámaras IP en el techo de un almacén donde no hay tomacorrientes. ¿Qué función del switch debe usarse?", ["Power over Ethernet", "Port mirroring", "Link aggregation", "Jumbo frames"], "PoE transporta energía y datos por el mismo cable de par trenzado hacia cámaras, teléfonos y access points. Port mirroring solo copia el tráfico para análisis.", [null, "Port mirroring copia el tráfico de un puerto a otro para monitoreo; no suministra energía.", "Link aggregation agrupa varios puertos para obtener más ancho de banda o redundancia, pero no alimenta dispositivos.", "Los jumbo frames permiten tramas Ethernet más grandes para mayor eficiencia en redes de almacenamiento; no tienen nada que ver con la energía."]],
  "ap20": ["Un técnico está configurando una red de 2.4 GHz para una oficina con tres access points. ¿Qué canales evitan la superposición?", ["1, 6 y 11", "1, 2 y 3", "3, 7 y 9", "4, 8 y 12"], "En la banda de 2.4 GHz solo los canales 1, 6 y 11 no se superponen en Norteamérica. Los canales con números vecinos comparten la mayor parte de sus frecuencias.", [null, "Los canales 1, 2 y 3 están separados solo 5 MHz, así que sus señales de unos 20 MHz de ancho se superponen mucho.", "Los canales 3, 7 y 9 están demasiado juntos; en particular, 7 y 9 se superponen casi por completo.", "Los canales 4, 8 y 12 están separados solo cuatro canales, así que aún se superponen, y el canal 12 no está permitido en Norteamérica."]],
  "ap21": ["¿Qué generación de Wi-Fi corresponde al estándar IEEE 802.11ax?", ["Wi-Fi 6", "Wi-Fi 4", "Wi-Fi 5", "Wi-Fi 3"], "802.11ax es Wi-Fi 6 (y Wi-Fi 6E cuando usa 6 GHz). 802.11ac es Wi-Fi 5 y 802.11n es Wi-Fi 4.", [null, "Wi-Fi 4 es 802.11n, el estándar anterior que introdujo MIMO en 2.4 y 5 GHz.", "Wi-Fi 5 es 802.11ac, que opera en 5 GHz y es anterior a 802.11ax.", "Wi-Fi 3 es el nombre retroactivo de 802.11g, un estándar de 2.4 GHz mucho más antiguo que 802.11ax."]],
  "ap22": ["El dueño de una oficina en casa quiere la seguridad más fuerte disponible en un nuevo router inalámbrico que admitan todos sus dispositivos. ¿Qué debe elegir?", ["WEP con una clave larga", "WPA con TKIP", "WPA3-Personal", "Una red abierta con filtrado MAC"], "WPA3-Personal usa SAE, que resiste los intentos de adivinar la contraseña sin conexión. WEP y TKIP están comprometidos, y el filtrado MAC es fácil de evadir.", ["WEP está comprometido sin importar la longitud de la clave y puede descifrarse en minutos capturando tráfico.", "El WPA original con TKIP tiene debilidades conocidas y está obsoleto; es mucho más débil que WPA3.", null, "Una red abierta deja el tráfico sin cifrar, y el filtrado MAC se evade fácilmente suplantando una dirección permitida."]],
  "ap23": ["Una empresa quiere que los empleados inicien sesión en el Wi-Fi con sus propias credenciales de dominio en lugar de una frase de acceso compartida. ¿Qué servidor necesita usar el access point?", ["Un servidor syslog", "Un servidor RADIUS", "Un servidor proxy", "Un servidor DHCP"], "WPA2/WPA3-Enterprise delega la autenticación a un servidor RADIUS (AAA) que verifica las credenciales de cada usuario. Un servidor DHCP solo entrega direcciones.", ["Un servidor syslog recopila mensajes de registro de los dispositivos; no autentica usuarios.", null, "Un servidor proxy reenvía y filtra las solicitudes web de los clientes; no verifica los inicios de sesión Wi-Fi.", "Un servidor DHCP solo asigna direcciones IP después de que un dispositivo se une; no realiza autenticación de usuarios."]],
  "ap24": ["La dirección de una impresora de red cambia constantemente, lo que rompe las asignaciones de impresión de los usuarios. ¿Cuál es la MEJOR solución en un router SOHO?", ["Acortar el tiempo de lease de DHCP", "Habilitar UPnP en el router", "Activar la DMZ del router", "Crear una reserva DHCP para su MAC"], "Una reserva siempre le da a la impresora la misma dirección sin perder la administración centralizada. Leases más cortos harían que la dirección cambiara aún más seguido.", ["Un lease más corto hace que los clientes renueven más seguido y aumenta la probabilidad de que la impresora reciba otra dirección.", "UPnP permite que los dispositivos abran puertos en el router automáticamente; no mantiene fija la IP de un dispositivo y es un riesgo de seguridad.", "Una DMZ expone un host a todo el tráfico entrante de internet, lo cual es riesgoso y no impide que la dirección cambie.", null]],
  "ap25": ["Un usuario aloja un servidor de juegos en su PC de casa y sus amigos no pueden conectarse desde internet. ¿Qué debe configurarse en el router SOHO?", ["Un nuevo SSID en la banda de 5 GHz", "Port forwarding a la IP privada de la PC", "Filtrado MAC para la PC", "Una entrada DNS estática para el router"], "Port forwarding envía el tráfico entrante de un puerto determinado a través de NAT hacia un host interno. Un nuevo SSID no hace nada por el tráfico entrante de internet.", ["Un nuevo SSID solo afecta a los clientes inalámbricos locales y no permite que el tráfico de internet llegue a la PC a través de NAT.", null, "El filtrado MAC controla qué dispositivos locales pueden unirse a la red; no permite conexiones entrantes desde internet.", "Una entrada DNS estática cambia cómo se resuelven los nombres y no enrutaría el tráfico entrante del juego a través de NAT hacia la PC."]],
  "ap26": ["¿Qué dirección es una dirección IPv4 privada que no se enrutará en la internet pública?", ["172.34.1.10", "172.20.5.4", "11.0.0.5", "193.168.1.20"], "Los rangos privados son 10.0.0.0/8, 172.16.0.0–172.31.255.255 y 192.168.0.0/16. 172.34.1.10 está fuera de 172.16–31, así que es pública.", ["172.34.1.10 está fuera del rango privado 172.16.0.0 a 172.31.255.255, así que es una dirección pública y enrutable.", null, "11.0.0.5 es pública; solo 10.0.0.0/8 es privado, así que un primer octeto de 11 no está en ningún rango privado.", "193.168.1.20 se parece a 192.168, pero es una dirección pública; solo 192.168.0.0/16 es privado."]],
  "ap27": ["Un administrador de correo quiere publicar qué servidores pueden enviar correo en nombre del dominio de la empresa para que los receptores rechacen el correo falsificado. ¿Qué registro DNS contiene esto?", ["Un registro MX", "Un registro CNAME", "Un registro AAAA", "Un registro TXT que contiene SPF"], "SPF se publica en un registro TXT y enumera los servidores de envío permitidos; DKIM y DMARC también usan registros TXT. Los registros MX solo indican a dónde entregar el correo entrante.", ["Un registro MX indica a los remitentes qué servidores aceptan el correo entrante del dominio; no autoriza remitentes salientes.", "Un registro CNAME convierte un nombre en alias de otro nombre y no contiene ninguna política de remitentes.", "Un registro AAAA asigna un nombre de host a una dirección IPv6 y no puede enumerar remitentes de correo autorizados.", null]],
  "ap28": ["Una empresa quiere que los dispositivos de invitados y las PC de contabilidad estén en los mismos switches físicos, pero en redes separadas. ¿Qué debe configurarse?", ["VLANs", "Una VPN", "Un servidor proxy", "NAT"], "Las VLANs dividen un switch en dominios de broadcast separados, de modo que el tráfico permanece aislado a menos que se enrute. Una VPN, en cambio, cifra el tráfico sobre redes no confiables.", [null, "Una VPN crea un túnel cifrado sobre una red no confiable; no separa dispositivos en los mismos switches locales.", "Un servidor proxy retransmite y filtra las solicitudes web de los clientes, pero no divide un switch en redes separadas.", "NAT traduce direcciones privadas a públicas en el borde de la red; no aísla grupos de dispositivos en los switches internos."]],
  "ap29": ["Una cabaña remota solo puede obtener internet satelital geoestacionario. ¿Qué problema debe esperar MÁS el propietario?", ["Alta latencia para videollamadas y juegos", "Ningún soporte para navegación web", "Conflictos frecuentes de direcciones DHCP", "Diafonía (crosstalk) en el cableado interior"], "Las señales deben viajar a un satélite a unos 36,000 km de altura y regresar, lo que agrega cientos de milisegundos de retraso. La navegación sigue funcionando, solo que con demora.", [null, "El internet satelital admite la navegación web normal; las páginas simplemente cargan con un retraso notable.", "Los conflictos de direcciones DHCP son un problema de la red local y no los causa el tipo de conexión a internet.", "El crosstalk es interferencia entre pares de cables en el cableado de cobre y no tiene nada que ver con el servicio satelital."]],
  "ap30": ["Un usuario conecta audífonos inalámbricos y un smartwatch a un teléfono. ¿Qué tipo de red forman estos dispositivos?", ["LAN", "PAN", "MAN", "SAN"], "Una red de área personal conecta dispositivos a pocos metros de una persona, normalmente por Bluetooth. Una SAN es una red dedicada al almacenamiento.", ["Una LAN conecta computadoras en un edificio u oficina, un alcance mucho mayor que el de los dispositivos que usa una persona.", null, "Una MAN abarca una ciudad o un campus, mucho más que unos pocos dispositivos alrededor de un usuario.", "Una SAN es una red dedicada de alta velocidad que conecta servidores con almacenamiento compartido, no dispositivos portátiles."]],
  "ap31": ["Un técnico está terminando nuevos tendidos Cat 6 en un bloque 110 en el cuarto de cableado. ¿Qué herramienta necesita?", ["Una herramienta de impacto (punchdown)", "Una crimpeadora RJ45", "Un conector loopback", "Un generador de tonos con sonda"], "Una herramienta punchdown asienta los cables en bloques 110 o Krone y los recorta. Una crimpeadora sirve para colocar conectores RJ45 en patch cords.", [null, "Una crimpeadora RJ45 coloca conectores modulares en los extremos de patch cords; no puede asentar cables en un bloque 110.", "Un conector loopback prueba un puerto devolviéndole su propia señal; no termina cables.", "Un generador de tonos con sonda rastrea e identifica cables, pero no se usa para terminarlos."]],
  "ap32": ["En un cuarto lleno de cables sin etiquetar, un técnico debe encontrar cuál llega a la toma de pared de la oficina 214. ¿Qué herramienta ayuda MÁS?", ["Un analizador Wi-Fi", "Un multímetro digital", "Un pelacables", "Un generador de tonos y sonda"], "El generador de tonos inyecta una señal en el cable desde la toma, y la sonda encuentra ese cable en el extremo del cuarto de cableado. Un analizador Wi-Fi solo examina señales inalámbricas.", ["Un analizador Wi-Fi mide señales y canales inalámbricos y no puede rastrear un cable de cobre.", "Un multímetro mide voltaje, resistencia y continuidad, pero no puede identificar un cable sin etiqueta dentro de un manojo en el extremo lejano.", "Un pelacables quita la cubierta del cable para terminarlo; no identifica cables.", null]],
  "ap33": ["Una pequeña empresa quiere que todo el tráfico web de las PC del personal pase por un servidor que almacene páginas en caché y filtre sitios bloqueados. ¿Qué dispositivo es adecuado?", ["Un balanceador de carga", "Un servidor DNS", "Un servidor syslog", "Un servidor proxy"], "Un proxy hace las solicitudes en nombre de los clientes y puede almacenar contenido en caché y filtrar URLs. Un balanceador de carga distribuye el tráfico entrante entre varios servidores.", ["Un balanceador de carga distribuye las solicitudes entrantes entre varios servidores; no almacena en caché ni filtra la navegación del personal.", "Un servidor DNS resuelve nombres a direcciones; el filtrado DNS puede bloquear algunos dominios, pero no almacena páginas web en caché para los clientes.", "Un servidor syslog solo recopila mensajes de registro de los dispositivos y no maneja tráfico web.", null]],
  "ap34": ["Un editor de fotos quiere los colores más precisos y amplios ángulos de visión en un monitor LCD económico. ¿Qué tipo de panel debe elegir?", ["TN", "VA", "IPS", "TN con retroiluminación CCFL"], "Los paneles IPS ofrecen la mejor precisión de color y los mejores ángulos de visión entre los tipos de LCD. Los paneles TN son rápidos, pero el color cambia al verlos en ángulo.", ["Los paneles TN son rápidos y baratos, pero tienen la peor precisión de color y los colores cambian notablemente en ángulo.", "Los paneles VA ofrecen alto contraste y negros profundos, pero su precisión de color y sus ángulos de visión generalmente quedan por debajo de IPS.", null, "CCFL es un tipo de retroiluminación antiguo y TN sigue teniendo mal color y malos ángulos, así que es peor que un panel IPS moderno."]],
  "ap35": ["Un gamer nota desenfoque de movimiento y quiere una animación más fluida. ¿Qué especificación del monitor importa MÁS?", ["Una relación de contraste más alta", "Una gama de colores más amplia", "Una tasa de refresco más alta", "Un tamaño de pantalla más grande"], "Una tasa de refresco más alta (144 Hz o más) dibuja más cuadros por segundo, lo que suaviza el movimiento. La relación de contraste afecta los negros y blancos, no la fluidez.", ["La relación de contraste define la diferencia entre la salida más oscura y la más brillante; no reduce el desenfoque de movimiento.", "Una gama de colores más amplia muestra más colores, pero no mejora la fluidez con que se dibuja el movimiento.", null, "Una pantalla más grande cambia el tamaño, no cuántos cuadros por segundo se muestran, así que no suaviza la animación."]],
  "ap36": ["Un técnico está instalando un nuevo SSD SATA en una PC de escritorio. ¿Qué dos cables necesita?", ["Un cable Molex y un cable eSATA", "Un cable de datos SATA y un cable de alimentación SATA", "Una cinta M.2 y un cable de ventilador de 4 pines", "Un cable de header USB y un cable de 24 pines"], "Las unidades SATA usan un cable de datos de 7 pines desde la placa base y un conector de alimentación SATA de 15 pines desde la PSU. Molex es un conector de alimentación de 4 pines más antiguo.", ["Molex es un conector de alimentación de 4 pines más antiguo, y eSATA es para unidades externas; ninguno forma el par estándar para un SSD SATA interno.", null, "Las unidades M.2 se conectan directamente a una ranura sin cinta, y un cable de ventilador de 4 pines alimenta ventiladores, no unidades.", "Los cables de header USB sirven para los puertos del panel frontal, y el cable de 24 pines alimenta la placa base, no el SSD."]],
  "ap37": ["Se debe tender cable por el espacio de retorno de aire sobre el cielo falso de un edificio de oficinas. ¿Qué cubierta de cable se requiere?", ["Clasificada plenum", "PVC clasificada riser", "De enterramiento directo", "Para exteriores con clasificación UV"], "Los espacios de manejo de aire requieren cubiertas clasificadas plenum, que desprenden menos humo tóxico al quemarse. El cable riser es para tendidos verticales entre pisos.", [null, "El cable riser está diseñado para tendidos verticales entre pisos, no para espacios de manejo de aire, y no cumple los requisitos de humo de plenum.", "El cable de enterramiento directo está hecho para ir bajo tierra sin conducto; su cubierta no está clasificada para espacios de aire plenum.", "El cable para exteriores con clasificación UV resiste el daño solar, pero no cumple el requisito de bajo humo de los espacios plenum."]],
  "ap38": ["¿Cuál es la longitud máxima recomendada de un tendido Cat 6 que transporta Ethernet entre un switch y un dispositivo?", ["100 metros", "50 metros", "185 metros", "500 metros"], "Los segmentos Ethernet de par trenzado están limitados a 100 metros. 185 m y 500 m eran los límites del antiguo Ethernet coaxial.", [null, "50 metros está muy dentro del límite; los segmentos Ethernet de par trenzado pueden llegar hasta 100 metros.", "185 metros era el límite de segmento del Ethernet coaxial delgado (10BASE2), no del par trenzado Cat 6.", "500 metros era el límite de segmento del Ethernet coaxial grueso (10BASE5), mucho más de lo que admite Cat 6."]],
  "ap39": ["Un usuario quiere conectar un monitor con un cable que transporte video y audio y que sea común en los televisores. ¿Qué conector es adecuado?", ["VGA", "DVI-D", "HDMI", "PS/2"], "HDMI transporta video y audio digitales y es estándar en televisores y monitores. DVI-D transporta solo video digital, y VGA solo video analógico.", ["VGA transporta solo video analógico, sin audio, y rara vez se encuentra en televisores modernos.", "DVI-D transporta video digital, pero normalmente no audio, y es poco común en televisores.", null, "PS/2 es un conector heredado para teclados y mouse y no transporta video ni audio."]],
  "ap40": ["Un técnico intenta instalar un módulo DDR4 en una ranura de placa base DDR5 y no entra. ¿Por qué?", ["Las ranuras DDR5 necesitan primero una actualización del BIOS", "El módulo debe instalarse en ángulo", "La CPU no está bien asentada", "La muesca está en una posición diferente"], "Cada generación DDR tiene su muesca en un lugar distinto para que no se puedan insertar módulos incompatibles. Las generaciones tampoco son compatibles eléctricamente.", ["Una actualización del BIOS no puede cambiar la ranura física; los módulos DDR4 simplemente no caben ni funcionan en ranuras DDR5.", "Los DIMM de escritorio se insertan rectos en la ranura; solo los SODIMM de laptop se insertan en ángulo, y el ángulo no corrige una muesca que no coincide.", "El asentamiento de la CPU no influye en si un módulo de memoria cabe físicamente en su ranura.", null]],
  "ap41": ["Una PC de escritorio tiene cuatro ranuras de memoria y dos módulos iguales. Siguiendo el manual de la placa base, ¿dónde deben ir para obtener el MEJOR rendimiento?", ["Ambos juntos en las ranuras 1 y 2", "En cualquier ranura, ya que la ubicación no influye", "En las ranuras 3 y 4, dejando la 1 y la 2 vacías para la refrigeración", "En las ranuras del mismo color para dual channel"], "Instalar módulos iguales en las ranuras emparejadas (a menudo identificadas por color) habilita el modo dual channel, que duplica el ancho de banda de la memoria.", ["Las ranuras adyacentes suelen estar en el mismo canal, así que colocar ambos módulos juntos puede dejar el sistema en modo single channel.", "La ubicación sí importa: los módulos en las ranuras equivocadas pueden funcionar en single channel con la mitad del ancho de banda de memoria.", "Dejar ranuras vacías no es por refrigeración; el manual indica las ranuras emparejadas que habilitan dual channel, que pueden ser o no la 3 y la 4.", null]],
  "ap42": ["Un servidor necesita memoria que pueda detectar y corregir errores de un solo bit. ¿Qué tipo debe pedirse?", ["SODIMM", "ECC", "DDR4 sin paridad", "RAM virtual"], "La memoria con código de corrección de errores (ECC) detecta y corrige errores de un solo bit, lo cual es importante en servidores. SODIMM describe un formato de laptop, no la corrección de errores.", ["SODIMM es un formato pequeño usado en laptops; no dice nada sobre corrección de errores.", null, "La memoria sin paridad no tiene bits adicionales para detectar ni corregir errores, que es lo contrario de lo que necesita el servidor.", "La RAM virtual es espacio en disco usado como extensión del archivo de paginación; no es un tipo de memoria física y no corrige errores."]],
  "ap43": ["Una oficina pequeña quiere un arreglo RAID que sobreviva a la falla de un disco y use la capacidad de forma eficiente. Tiene cuatro discos. ¿Qué nivel de RAID es el MÁS adecuado?", ["RAID 5", "RAID 0", "RAID 1", "Volumen distribuido (spanned)"], "RAID 5 distribuye datos con paridad en tres o más discos y sobrevive a una falla perdiendo solo la capacidad de un disco. RAID 0 no tiene redundancia.", [null, "RAID 0 distribuye datos sin redundancia, así que la falla de un solo disco pierde todo el arreglo.", "RAID 1 hace espejo de los discos y sobrevive a una falla, pero con cuatro discos desperdicia la mitad de la capacidad, por lo que es menos eficiente que RAID 5.", "Un volumen distribuido solo une discos uno tras otro sin redundancia, así que la falla de un disco pierde datos."]],
  "ap44": ["¿Cuál es el número mínimo de discos necesarios para RAID 10?", ["Dos", "Tres", "Cuatro", "Cinco"], "RAID 10 es un striping de espejos, así que necesita al menos dos pares en espejo, es decir, cuatro discos. RAID 1 necesita dos y RAID 5 necesita tres.", ["Dos discos es el mínimo para RAID 1 (espejo) o RAID 0, pero RAID 10 necesita al menos dos pares en espejo.", "Tres discos es el mínimo para RAID 5; RAID 10 no puede construirse con un número impar de discos.", null, "Cinco discos es más de lo necesario, y RAID 10 usa un número par de discos porque se construye con pares en espejo."]],
  "ap45": ["Un usuario quiere ejecutar Windows 11, que requiere TPM y Secure Boot. ¿Dónde debe verificar el técnico que ambos estén habilitados?", ["En el Administrador de dispositivos, en Unidades de disco", "En la página de administración del router", "En la configuración del firmware UEFI", "En el selector de voltaje de la PSU"], "TPM (a menudo llamado PTT o fTPM) y Secure Boot se activan en la configuración del firmware UEFI. El Administrador de dispositivos no puede habilitar funciones del firmware.", ["La categoría Unidades de disco del Administrador de dispositivos enumera dispositivos de almacenamiento; no puede mostrar ni habilitar la configuración de TPM y Secure Boot del firmware.", "La página de administración del router configura la red y no tiene acceso a las funciones de seguridad del firmware de la PC.", null, "El selector de voltaje de una PSU elige el voltaje de entrada de CA y no tiene nada que ver con TPM ni con Secure Boot."]],
  "ap46": ["Un técnico arma una PC pequeña para la sala y debe elegir el formato de placa base común más pequeño. ¿Cuál es adecuado?", ["ATX", "Mini-ITX", "microATX", "Extended ATX"], "Las placas Mini-ITX miden 17 x 17 cm, más pequeñas que microATX y ATX. Extended ATX es la más grande y es adecuada para estaciones de trabajo.", ["ATX es la placa de escritorio estándar de tamaño completo, de unos 30.5 x 24.4 cm, mucho más grande que Mini-ITX.", null, "microATX es más pequeña que ATX, pero sigue siendo más grande que Mini-ITX, así que no es la opción común más pequeña.", "Extended ATX es el formato común más grande y está pensado para estaciones de trabajo y servidores, no para equipos pequeños de sala."]],
  "ap47": ["Después de instalar un nuevo disipador de CPU, una PC de escritorio se apaga a los pocos minutos bajo carga. El técnico descubre que se limpió la pasta térmica anterior. ¿Qué se omitió MÁS probablemente?", ["Aplicar pasta térmica nueva", "Actualizar el driver del chipset", "Configurar la RAM en dual channel", "Habilitar el TPM en el firmware"], "La pasta térmica llena los pequeños huecos entre la CPU y el disipador; sin ella la CPU se sobrecalienta y se apaga. Los drivers no afectan la transferencia de calor.", [null, "Los drivers del chipset administran funciones de la placa base en el sistema operativo y no influyen en la transferencia de calor de la CPU.", "La memoria en dual channel afecta el ancho de banda, no la refrigeración de la CPU, y no causaría apagados térmicos.", "El TPM almacena claves criptográficas y no tiene relación con la temperatura de la CPU."]],
  "ap48": ["Un usuario planea agregar una tarjeta gráfica de gama alta a una PC de escritorio. ¿Qué debe verificar el técnico antes de comprar?", ["Que el gabinete tenga un puerto USB-C en el panel frontal", "Que el adaptador de red admita Wi-Fi 6", "Que el monitor use un conector VGA", "Que la PSU tenga suficiente potencia y conectores de alimentación"], "Las GPU potentes consumen mucha corriente y necesitan conectores de alimentación PCIe, así que la PSU debe tener la capacidad y los cables. Los puertos del panel frontal no importan.", ["Un puerto USB-C frontal es una función de comodidad y no influye en si se puede instalar una tarjeta gráfica.", "La compatibilidad con Wi-Fi 6 del adaptador de red no tiene relación con instalar ni alimentar una tarjeta gráfica.", "Las tarjetas modernas de gama alta rara vez tienen salidas VGA, y el conector del monitor no es la verificación clave previa a la compra en cuanto a energía y espacio.", null]],
  "ap49": ["Un servidor tiene dos fuentes de alimentación conectadas a circuitos separados. ¿Cuál es el principal beneficio?", ["Duplica la potencia disponible para la CPU", "Convierte CC de nuevo a CA para el UPS", "Sigue funcionando si una fuente falla", "Permite que el servidor use ventiladores de 3.3 V"], "Las PSU redundantes permiten que el sistema siga funcionando cuando falla una fuente o un circuito. Comparten la carga para dar resiliencia, no para duplicar la potencia disponible.", ["Las fuentes redundantes comparten la carga para tolerancia a fallos; la potencia utilizable para la CPU no se duplica.", "Las PSU convierten CA en CC para los componentes; no devuelven CC a un UPS.", null, "El voltaje de los ventiladores lo definen los rieles de la fuente, no el tener una segunda fuente, y los ventiladores suelen funcionar a 12 V."]],
  "ap50": ["¿Qué voltajes proporciona una fuente de alimentación ATX estándar a los componentes?", ["1.5 V, 9 V y 24 V", "5 V, 48 V y 120 V", "12 V, 110 V y 220 V", "3.3 V, 5 V y 12 V"], "Las fuentes ATX entregan rieles de 3.3, 5 y 12 V de CC. 110/220 V es la entrada de CA desde el tomacorriente, no la salida hacia los componentes.", ["Estos no son voltajes de riel ATX; 1.5 V es típico de la memoria DDR3 y lo fijan reguladores integrados, y 9 V y 24 V no son salidas ATX.", "48 V es típico de PoE y equipos de telecomunicaciones, y 120 V es la corriente alterna del tomacorriente, no una salida de CC hacia los componentes.", "110 V y 220 V son voltajes de entrada de CA desde el tomacorriente; aquí solo 12 V es un riel de salida ATX real.", null]],
  "ap51": ["Una impresora láser imprime una página. ¿Qué paso viene justo después de transferir la imagen al papel?", ["Exposición", "Carga", "Revelado", "Fusión"], "El orden es procesamiento, carga, exposición, revelado, transferencia, fusión y limpieza. La fusión derrite el tóner sobre el papel después de la transferencia.", ["La exposición ocurre antes de la transferencia, cuando el láser escribe la imagen en el tambor cargado.", "La carga ocurre al principio, cuando el tambor recibe una carga uniforme antes de la exposición.", "El revelado, cuando el tóner es atraído al tambor expuesto, ocurre antes de transferir la imagen al papel.", null]],
  "ap52": ["Un mostrador de envíos imprime recibos en papel sensible al calor sin tinta ni tóner. ¿Qué tipo de impresora es?", ["De impacto", "De inyección de tinta", "Láser a color", "Térmica"], "Las impresoras térmicas calientan un papel especial para crear la imagen. Las impresoras de impacto golpean una cinta entintada, lo que es adecuado para formularios de varias copias.", ["Las impresoras de impacto golpean una cinta entintada contra el papel; sí usan tinta, así que no coinciden con esta descripción.", "Las impresoras de inyección de tinta rocían tinta líquida sobre papel común, así que no prescinden de la tinta.", "Las impresoras láser a color fusionan tóner sobre la página, lo que contradice la descripción sin tóner.", null]],
  "ap53": ["Una oficina debe imprimir facturas de varias copias con papel carbón. ¿Qué tipo de impresora se requiere?", ["Térmica", "De inyección de tinta", "De impacto", "3D"], "Solo una impresora de impacto (matriz de puntos) golpea físicamente la página con suficiente fuerza para marcar todas las copias de un formulario múltiple.", ["Las impresoras térmicas calientan un papel especial y no pueden presionar para marcar las copias debajo de la hoja superior.", "Las impresoras de inyección rocían tinta solo en la hoja superior y no pueden hacer copias con carbón o autocopiativas.", null, "Una impresora 3D construye objetos físicos con filamento o resina y no imprime en formularios de papel."]],
  "ap54": ["Una impresora láser muestra un mensaje de 'reemplazar kit de mantenimiento' después de 200,000 páginas. ¿Qué piezas suele contener el kit?", ["Unidad fusora y rodillos", "Cartucho de tóner y tambor", "Cartuchos de tinta y cabezal de impresión", "Cinta y rodillo platen"], "Los kits de mantenimiento láser suelen contener una unidad fusora, rodillos de recogida y alimentación y almohadillas de separación. El tóner se reemplaza por separado y con más frecuencia.", [null, "El cartucho de tóner y el tambor son consumibles que se reemplazan por separado y mucho más seguido que un kit de mantenimiento.", "Los cartuchos de tinta y los cabezales de impresión pertenecen a las impresoras de inyección de tinta, no a las láser.", "Las cintas y los rodillos platen son partes de las impresoras de impacto, no de las láser."]],
  "ap55": ["Los usuarios quieren que una impresora compartida de la oficina imprima por ambos lados de forma predeterminada para ahorrar papel. ¿Dónde debe configurarlo el técnico?", ["En la opción dúplex de las propiedades de la impresora", "En la orientación del papel en la aplicación", "En la opción de intercalar del cuadro de impresión", "En la configuración de dirección IP de la impresora"], "Configurar el dúplex como predeterminado en las propiedades de la impresora o en el propio dispositivo lo aplica a todos los trabajos. Intercalar solo ordena varias copias.", [null, "La orientación define el diseño vertical u horizontal y no hace que la impresora use ambos lados del papel.", "Intercalar controla el orden de las páginas de varias copias, no la impresión a doble cara.", "La dirección IP solo determina cómo llegan los clientes a la impresora; no influye en el dúplex."]],
  "ap56": ["Un técnico instala un hipervisor directamente sobre el hardware bare-metal de un servidor, sin sistema operativo anfitrión. ¿De qué tipo es?", ["Tipo 2", "Tipo 1", "Runtime de contenedores", "Emulador"], "Un hipervisor Tipo 1 se ejecuta directamente sobre el hardware. Un hipervisor Tipo 2, como VirtualBox, se ejecuta como aplicación sobre un sistema operativo anfitrión.", ["Un hipervisor Tipo 2, como VirtualBox, se ejecuta como aplicación sobre un sistema operativo anfitrión.", null, "Un runtime de contenedores ejecuta aplicaciones aisladas que comparten el kernel del sistema anfitrión, así que necesita un sistema operativo anfitrión.", "Un emulador imita hardware diferente por software, normalmente sobre un sistema operativo anfitrión, en lugar de ejecutarse directamente sobre bare metal."]],
  "ap57": ["VirtualBox se niega a iniciar una máquina virtual de 64 bits e indica que la virtualización por hardware no está disponible. ¿Qué debe verificar el técnico PRIMERO?", ["Que la VM tenga una segunda NIC virtual", "Que VT-x o AMD-V esté habilitado en UEFI", "Que el anfitrión tenga una GPU dedicada", "Que el invitado tenga Secure Boot deshabilitado"], "Los invitados de 64 bits necesitan las extensiones de virtualización de la CPU, que a menudo están desactivadas en el firmware. La cantidad de NIC virtuales no tiene nada que ver con este error.", ["Las NIC virtuales afectan la red dentro de la VM; no causan un error de virtualización por hardware.", null, "No se requiere una GPU dedicada para la virtualización por hardware; lo que importa son las extensiones de la CPU.", "Secure Boot en el invitado afecta qué cargadores de arranque acepta la VM, no si el anfitrión expone VT-x o AMD-V."]],
  "ap58": ["Un analista quiere abrir un archivo sospechoso sin poner en riesgo la red de la empresa. ¿Qué uso de la virtualización es el MÁS adecuado?", ["Una VM en modo bridge conectada a la LAN de producción", "Una VM sandbox sin red", "Un contenedor que comparte los archivos del anfitrión", "Una VM en la nube con dirección IP pública"], "Una VM sandbox aislada contiene cualquier daño y puede revertirse desde un snapshot. Conectarla en bridge a la LAN expondría otros sistemas.", ["Conectar la VM en bridge a la LAN de producción le da a cualquier malware del archivo un camino directo a los sistemas de la empresa.", null, "Un contenedor que comparte archivos del anfitrión permite que el malware llegue a los datos del anfitrión, y los contenedores además comparten el kernel, así que el aislamiento es más débil.", "Una VM en la nube con IP pública expone el sistema de prueba a internet, y no está aislada solo por ser remota."]],
  "ap59": ["¿En qué se diferencian los contenedores de las máquinas virtuales?", ["Cada uno incluye un sistema operativo invitado completo", "Requieren un hipervisor Tipo 1", "Comparten el kernel del sistema operativo anfitrión", "No pueden ejecutarse en Linux"], "Los contenedores empaquetan una aplicación y sus dependencias, pero comparten el kernel del anfitrión, así que son más ligeros que las VM, cada una de las cuales ejecuta un sistema operativo completo.", ["Cada VM incluye un sistema operativo invitado completo; los contenedores, en cambio, comparten el kernel del anfitrión, por eso son más ligeros.", "Los contenedores se ejecutan en un sistema operativo anfitrión normal con un motor de contenedores y no necesitan un hipervisor Tipo 1.", null, "Los contenedores se originaron en Linux y se ejecutan ahí de forma nativa, así que esta afirmación es lo contrario de la realidad."]],
  "ap60": ["Una empresa usa una aplicación contable de los años 90 que solo funciona en un sistema operativo antiguo. ¿Cómo puede seguir usándola en hardware nuevo?", ["Ejecutar el sistema operativo antiguo en una máquina virtual", "Instalar la aplicación directamente en Windows 11", "Mover la aplicación a una plataforma de correo SaaS", "Reemplazar la PSU por un modelo antiguo"], "La virtualización permite ejecutar sistemas operativos y aplicaciones heredados en hardware moderno dentro de una VM aislada. Los sistemas operativos más nuevos podrían no ejecutar la aplicación antigua.", [null, "La aplicación solo funciona en el sistema operativo antiguo, así que instalarla en Windows 11 es justamente lo que probablemente fallará.", "Una plataforma de correo SaaS no ejecuta software contable personalizado; migrar a ella no conservaría la aplicación heredada.", "La PSU suministra energía y no tiene nada que ver con la compatibilidad del sistema operativo ni de las aplicaciones."]],
  "ap61": ["Una empresa alquila servidores virtuales a un proveedor y administra por su cuenta el sistema operativo, los parches y las aplicaciones. ¿Qué modelo de servicio en la nube es este?", ["SaaS", "PaaS", "IaaS", "DaaS"], "Con IaaS el proveedor suministra cómputo, almacenamiento y red, y el cliente administra todo desde el sistema operativo hacia arriba. Con SaaS el cliente solo usa la aplicación.", ["Con SaaS el proveedor opera toda la pila de la aplicación y el cliente solo usa el software, sin administrar sistema operativo ni parches.", "Con PaaS el proveedor administra el sistema operativo y el runtime, y el cliente solo despliega código, no parches del sistema operativo.", null, "Desktop as a Service entrega escritorios virtuales a los usuarios; no es alquilar servidores para administrar todo el sistema operativo y las aplicaciones."]],
  "ap62": ["Los servidores web en la nube de un minorista agregan capacidad automáticamente durante las ventas de temporada y la reducen después. ¿Qué característica de la nube es esta?", ["Multitenencia", "Elasticidad rápida", "Responsabilidad compartida", "Sincronización de archivos"], "La elasticidad rápida significa que los recursos crecen y se reducen rápidamente según la demanda. La multitenencia significa que muchos clientes comparten la infraestructura del proveedor.", ["La multitenencia significa que muchos clientes comparten la infraestructura del proveedor; no describe el escalado automático.", null, "La responsabilidad compartida divide las tareas de seguridad entre el proveedor y el cliente; no se trata de escalar capacidad.", "La sincronización de archivos mantiene actualizadas las copias de archivos entre dispositivos y no tiene nada que ver con la capacidad de los servidores."]],
  "ap63": ["Una empresa mantiene bases de datos sensibles en su propio centro de datos, pero ejecuta su sitio web público en un proveedor de nube, con ambos conectados. ¿Qué modelo de implementación es este?", ["Nube comunitaria", "Nube privada", "Nube híbrida", "Nube pública"], "Una nube híbrida combina nubes privadas y públicas que trabajan juntas. Una nube comunitaria la comparten organizaciones con necesidades comunes.", ["Una nube comunitaria la comparten varias organizaciones con necesidades comunes, no es el centro de datos propio de una empresa más un proveedor público.", "Una nube privada la usa una sola organización y no incluye el sitio web en la nube pública.", null, "Una nube puramente pública pondría todo, incluidas las bases de datos sensibles, en la infraestructura del proveedor."]],
  "ap64": ["Una empresa paga a su proveedor de nube solo por las horas de cómputo y el almacenamiento que realmente usa cada mes. ¿Qué característica describe esto?", ["Alta disponibilidad", "Uso medido", "Elasticidad rápida", "Responsabilidad compartida"], "El uso medido registra el consumo para que los clientes paguen por lo que usan. La elasticidad rápida se refiere al escalado, no a la facturación.", ["La alta disponibilidad significa mantener los servicios funcionando a pesar de las fallas; no describe cómo se factura el uso.", null, "La elasticidad rápida describe cómo se aumentan y reducen los recursos según la demanda, no el pago por uso.", "La responsabilidad compartida divide las tareas de seguridad entre el proveedor y el cliente; no es un modelo de facturación."]],
  "ap65": ["Los empleados inician sesión en escritorios que se ejecutan en servidores centrales y se transmiten a thin clients. ¿Cómo se llama esto?", ["NAS", "SDN", "KVM", "VDI"], "La infraestructura de escritorios virtuales (VDI) aloja VM de escritorio de forma centralizada y las transmite a los clientes. Un NAS proporciona almacenamiento de archivos.", ["Un NAS es un equipo de almacenamiento de archivos en la red; no aloja ni transmite escritorios.", "Las redes definidas por software separan el control de la red del hardware de reenvío; no entregan escritorios.", "Un switch KVM comparte un teclado, video y mouse entre varias computadoras locales; no transmite escritorios virtuales.", null]],
  "ap66": ["Un técnico identificó un problema e interrogó al usuario. ¿Cuál es el siguiente paso en la metodología de solución de problemas de CompTIA?", ["Implementar la solución", "Documentar hallazgos y resultados", "Establecer una teoría de la causa probable", "Verificar la funcionalidad completa del sistema"], "El orden es identificar, formular una teoría, probar la teoría, planificar, implementar, verificar y documentar. La implementación llega solo después de probar la teoría y elaborar un plan.", ["Implementar una solución ocurre solo después de probar la teoría y elaborar un plan de acción.", "La documentación es el último paso, después de implementar y verificar la solución.", null, "Verificar la funcionalidad completa ocurre después de implementar una solución, mucho más adelante en el proceso."]],
  "ap67": ["Antes de reemplazar un disco que está fallando en la PC de un usuario, ¿qué debe hacer el técnico como parte de la identificación del problema?", ["Respaldar los datos del usuario si es posible", "Pedir una placa base de reemplazo", "Documentar las lecciones aprendidas", "Escalar al fabricante"], "Identificar el problema incluye hacer respaldos antes de realizar cambios y preguntar por cambios recientes. La documentación va al final del proceso.", [null, "Pedir una placa base es prematuro e incorrecto para un disco que falla; las piezas se piden después de confirmar la causa.", "Documentar las lecciones aprendidas pertenece al paso final, no a la identificación del problema.", "El escalamiento ocurre cuando no se puede confirmar una teoría o resolver el problema, no como parte de la identificación inicial."]],
  "ap68": ["La teoría de un técnico sobre una tarjeta de red defectuosa resulta incorrecta después de probarla. ¿Qué debe ocurrir a continuación?", ["Implementar de todos modos la solución original", "Establecer una nueva teoría o escalar", "Documentar el problema como resuelto", "Verificar la funcionalidad completa del sistema"], "Si la teoría no se confirma, hay que establecer una nueva teoría o escalar. Aplicar una solución no comprobada desperdicia tiempo y puede causar nuevos problemas.", ["Aplicar una solución basada en una teoría descartada desperdicia tiempo y puede introducir nuevos problemas sin resolver el real.", null, "El problema no está resuelto, así que registrarlo como solucionado sería inexacto y dejaría al usuario sin solución.", "La verificación viene después de implementar una solución que funcione; todavía no hay nada que verificar."]],
  "ap69": ["La fecha y hora de una PC de escritorio vuelven a un valor predeterminado cada vez que se desconecta. ¿Cuál es la causa MÁS probable?", ["Una batería CMOS agotada", "Un disco duro que está fallando", "Un driver de gráficos desactualizado", "Un cable SATA flojo"], "La batería CMOS/RTC mantiene el reloj y la configuración del firmware sin alimentación de CA. Si está débil, se pierden cada vez que se retira la energía.", [null, "Un disco duro que falla causa lentitud, errores o fallas de arranque, pero no reinicia el reloj del firmware.", "Un driver de gráficos afecta la salida de video en el sistema operativo y no interviene en mantener la hora cuando se retira la energía.", "Un cable SATA flojo causa problemas de detección del disco, no la pérdida de la fecha y la hora."]],
  "ap70": ["Una PC enciende y sus ventiladores giran, pero no hay imagen y la placa base emite pitidos en un patrón repetitivo. ¿Qué debe revisar el técnico PRIMERO?", ["Los registros del Visor de eventos de Windows", "La calibración de color del monitor", "La configuración de distribución del teclado", "El significado del código POST en el manual de la placa"], "Los códigos de pitidos provienen del POST antes de que cargue el sistema operativo, y el manual asocia cada patrón con una falla, como de memoria o video. Los registros de Windows aún no existen.", ["Los códigos de pitidos ocurren durante el POST, antes de que inicie Windows, así que el Visor de eventos no tiene entradas sobre esta falla.", "La calibración de color ajusta cómo se ve una pantalla que ya funciona; no explica la falta de imagen junto con los pitidos.", "La distribución del teclado es una configuración del sistema operativo y no tiene nada que ver con los pitidos del POST.", null]],
  "ap71": ["Una estación de trabajo muestra pantallas azules aleatorias con diferentes códigos de detención, y la semana pasada se instaló un nuevo módulo de memoria. ¿Qué debe ejecutar el técnico?", ["Un desfragmentador de disco", "Un vaciado de la caché DNS", "Una página de prueba de impresora", "Un diagnóstico de memoria"], "Los errores de detención aleatorios después de un cambio de memoria sugieren RAM defectuosa o incompatible; Windows Memory Diagnostic o MemTest86 la pondrán a prueba.", ["Desfragmentar reorganiza los archivos en un disco duro y no detecta memoria defectuosa.", "Vaciar la caché DNS borra las búsquedas de nombres almacenadas y no puede causar ni diagnosticar pantallas azules.", "Una página de prueba de impresora solo verifica la impresión y no tiene relación con los bloqueos del sistema.", null]],
  "ap72": ["Un técnico huele a quemado y encuentra capacitores hinchados y con fugas en una placa base. ¿Cuál es la acción correcta?", ["Actualizar el BIOS y volver a probar", "Volver a asentar los módulos de RAM", "Reemplazar la placa base", "Aplicar pasta térmica nueva"], "Los capacitores abultados o con fugas son una falla física que las actualizaciones de firmware no pueden corregir; la placa debe reemplazarse.", ["Una actualización del BIOS es software y no puede reparar capacitores dañados físicamente; además, la placa podría fallar durante la actualización.", "Volver a asentar la RAM resuelve contactos de memoria flojos, no capacitores hinchados o con fugas en la placa.", null, "La pasta térmica mejora la refrigeración de la CPU, pero no hace nada por capacitores dañados."]],
  "ap73": ["Una PC se apaga después de unos 20 minutos de juego y el gabinete se siente muy caliente. ¿Qué causa debe revisar el técnico PRIMERO?", ["Una dirección de servidor DNS incorrecta", "Ventiladores obstruidos o acumulación de polvo", "Un perfil de usuario dañado", "Una cola de impresión llena"], "Los apagados por calor apuntan a problemas de refrigeración, como polvo, ventiladores dañados o pasta térmica seca. El DNS y los perfiles no causan apagados repentinos.", ["Un servidor DNS incorrecto impide la resolución de nombres, pero no puede hacer que una PC se sobrecaliente y se apague.", null, "Un perfil de usuario dañado causa problemas de inicio de sesión o de configuración, no apagados por calor.", "Una cola de impresión llena retrasa la impresión y no afecta la temperatura ni la energía del sistema."]],
  "ap74": ["Un disco duro hace un fuerte ruido de clic y el sistema se volvió muy lento. ¿Qué debe hacer el técnico?", ["Desfragmentar el disco para eliminar el ruido", "Aumentar el tamaño del archivo de paginación", "Deshabilitar las alertas S.M.A.R.T. en el firmware", "Respaldar los datos y reemplazar el disco"], "El clic suele indicar un cabezal de lectura/escritura que está fallando; hay que rescatar los datos mientras se pueda y reemplazar el disco. Desfragmentar exige demasiado a un disco que falla.", ["Desfragmentar no puede corregir una falla mecánica y somete a una gran carga de lectura/escritura a un disco que podría estar a punto de fallar.", "Un archivo de paginación más grande no resuelve el problema del disco y pondría el archivo de paginación en el hardware defectuoso.", "Deshabilitar las alertas S.M.A.R.T. solo oculta las advertencias y no protege los datos.", null]],
  "ap75": ["Una PC muestra 'Bootable device not found' después de que un técnico agregó un segundo disco. ¿Cuál es la solución MÁS probable?", ["Reemplazar la fuente de alimentación de la PC", "Corregir el orden de arranque en UEFI", "Actualizar el driver de video", "Reiniciar el router"], "Agregar un disco puede cambiar el orden de arranque, de modo que el firmware intente primero el disco nuevo y vacío. La PSU funciona si la PC llega a mostrar este mensaje.", ["La PC enciende y muestra un mensaje del firmware, así que la fuente de alimentación funciona.", null, "El driver de video se carga con el sistema operativo; este error ocurre antes de que se cargue cualquier sistema operativo o driver.", "El router no tiene nada que ver con los dispositivos de arranque locales, así que reiniciarlo no corrige este error."]],
  "ap76": ["Un arreglo RAID 1 muestra el estado 'degraded' en la utilidad de administración. ¿Qué significa esto?", ["Uno de los discos miembro falló o salió del arreglo", "El arreglo se está reconstruyendo más rápido de lo normal", "Todos los datos del arreglo ya se perdieron", "El arreglo se convirtió en RAID 0"], "Degraded significa que el arreglo funciona sin redundancia completa; hay que reemplazar el disco dañado y dejar que se reconstruya antes de que falle un segundo disco.", [null, "La reconstrucción ocurre después de reemplazar un disco dañado; degraded significa que falta redundancia en este momento, no que se esté reconstruyendo rápido.", "Los datos de un RAID 1 degradado siguen disponibles en el disco restante, aunque ya no están protegidos.", "Los niveles de RAID no cambian por sí solos; degraded describe un miembro faltante o dañado, no una conversión."]],
  "ap77": ["CrystalDiskInfo muestra un estado de precaución con un conteo creciente de sectores reasignados en el disco de una laptop. ¿Qué indica esto?", ["El disco necesita desfragmentarse", "El sistema de archivos es FAT32 en lugar de NTFS", "El firmware del disco es demasiado nuevo", "El disco está fallando y debe reemplazarse pronto"], "Los sectores reasignados de S.M.A.R.T. significan que el disco está reubicando zonas dañadas, una advertencia de falla inminente. Hay que respaldar y planificar un reemplazo.", ["Los sectores reasignados son una advertencia de salud física; desfragmentar solo reorganiza archivos y exige más al disco.", "El tipo de sistema de archivos no afecta los atributos S.M.A.R.T. como el conteo de sectores reasignados.", "Un firmware más nuevo no provoca un aumento de sectores reasignados; ese atributo refleja el desgaste físico del medio.", null]],
  "ap78": ["La pantalla de una laptop se ve muy oscura, pero al iluminarla con una linterna se distingue la imagen débilmente. ¿Qué componente es MÁS probable que esté fallando?", ["El digitalizador", "La retroiluminación", "El driver de la GPU", "La antena Wi-Fi"], "Una imagen tenue bajo una linterna muestra que el LCD está dibujando la imagen, pero no se está iluminando, lo que apunta a la retroiluminación o a su alimentación.", ["El digitalizador maneja la entrada táctil y no ilumina la pantalla.", null, "Un problema del driver de la GPU distorsionaría la imagen o no la dibujaría, pero aquí la imagen está presente y simplemente no está iluminada.", "Las antenas Wi-Fi pasan por la tapa de la pantalla, pero no intervienen en la iluminación de la pantalla."]],
  "ap79": ["Un monitor nuevo muestra texto borroso y la imagen parece estirada. ¿Qué debe revisar el técnico PRIMERO?", ["Que el monitor tenga píxeles muertos", "Que la tasa de refresco esté en su mínimo", "Que la resolución coincida con la resolución nativa", "Que el cable esté clasificado plenum"], "Los LCD se ven nítidos solo en su resolución nativa; otras configuraciones se escalan y se ven borrosas. Los píxeles muertos aparecen como puntos fijos, no como desenfoque.", ["Los píxeles muertos se ven como puntos fijos negros o de color, no como texto borroso y una imagen estirada.", "Bajar la tasa de refresco no corrige el escalado y podría causar parpadeo u otros problemas; el problema es la resolución.", null, "La clasificación plenum se refiere a la seguridad contra incendios en espacios de aire y no afecta la nitidez de la imagen."]],
  "ap80": ["Un proyector se apaga constantemente después de 30 minutos en una sala de conferencias. Su lámpara es nueva. ¿Qué debe revisar el técnico?", ["El cable HDMI por si tiene pines doblados", "La resolución de pantalla de la laptop", "El ajuste keystone del proyector", "El filtro de aire y las rejillas por si están obstruidos"], "Los proyectores se sobrecalientan y se apagan cuando los filtros o las rejillas están obstruidos. El keystone solo corrige la forma de la imagen.", ["Los pines HDMI doblados causarían falta de video o fallas en la imagen, no un apagado después de cierto tiempo.", "La resolución de la laptop afecta la imagen, pero no hace que el proyector se apague al calentarse.", "La corrección keystone solo arregla una imagen trapezoidal y no puede causar apagados.", null]],
  "ap81": ["Un teléfono tarda horas en cargar y solo carga cuando el cable se sostiene en ángulo. ¿Qué debe revisar el técnico PRIMERO?", ["El brillo de la pantalla del teléfono", "La configuración de llamadas por Wi-Fi", "El espacio de almacenamiento del teléfono", "El puerto de carga por si tiene pelusa"], "La pelusa acumulada en el puerto impide que el conector entre por completo. Limpiarlo con cuidado a menudo resuelve la carga sin reemplazar el puerto.", ["El brillo afecta qué tan rápido se agota la batería, pero no puede hacer que la carga dependa del ángulo del cable.", "Las llamadas por Wi-Fi solo enrutan las llamadas por Wi-Fi y no afectan la conexión física de carga.", "El almacenamiento lleno hace más lento el teléfono, pero no impide que el conector de carga haga contacto.", null]],
  "ap82": ["Un smartphone se calentó al tacto y su batería se agota rápido, incluso en reposo. ¿Qué debe revisar el técnico PRIMERO?", ["Aplicaciones con alto uso de CPU en segundo plano", "La funda y el protector de pantalla instalados", "El nivel de volumen del tono de llamada", "El PIN de la tarjeta SIM"], "Las aplicaciones descontroladas mantienen ocupado el procesador, lo que agota la batería y genera calor. Hay que revisar el uso de batería por aplicación y cerrar o actualizar la culpable.", [null, "Una funda puede retener algo de calor, pero no explica que la batería se agote rápido con el teléfono en reposo.", "El volumen del tono solo consume energía cuando suena el teléfono y no causa calor constante ni consumo en reposo.", "El PIN de la SIM solo protege la tarjeta SIM y no afecta el calor ni el uso de batería."]],
  "ap83": ["El puntero del mouse de una laptop se desplaza solo por la pantalla cuando nadie lo toca. ¿Cuál es una causa probable?", ["Una batería CMOS agotada", "Contaminación en el touchpad", "Un servidor DNS incorrecto", "Una tasa de refresco de pantalla incorrecta"], "La humedad, la suciedad o una batería hinchada que presiona el touchpad pueden causar desplazamiento del cursor. Hay que limpiar el panel, revisar la configuración del touchpad e inspeccionar la batería.", ["Una batería CMOS agotada reinicia el reloj y la configuración del firmware; no mueve el puntero.", null, "La configuración DNS solo afecta la resolución de nombres y no puede mover el puntero del mouse.", "La tasa de refresco controla con qué frecuencia se redibuja la pantalla y no haría que el puntero se desplace."]],
  "ap84": ["Las páginas de una impresora láser salen con tóner que se corre o se borra fácilmente. ¿Qué componente es MÁS probable que esté fallando?", ["El rodillo de recogida", "La cuchilla de limpieza de la banda de transferencia", "El fusor", "La interfaz de red"], "El fusor usa calor y presión para adherir el tóner; si falla, el tóner no se derrite sobre la página y se corre. Los rodillos de recogida solo alimentan el papel.", ["Un rodillo de recogida gastado causa alimentaciones incorrectas o atascos, no tóner que no se adhiere al papel.", "La cuchilla de limpieza retira el tóner sobrante; si falla causa rayas o imágenes fantasma, no tóner sin fundir que se borra.", null, "La interfaz de red solo recibe los trabajos de impresión y no influye en cómo se adhiere el tóner al papel."]],
  "ap85": ["Cada página de una impresora láser muestra una copia tenue de una imagen anterior más abajo en la página. ¿Cómo se llama esto y cuál es la causa habitual?", ["Impresión ilegible por un driver incorrecto", "Imagen fantasma por un tambor o limpieza desgastados", "Atascos de papel por rodillos de alimentación gastados", "Impresión desvanecida por poco tóner"], "Las imágenes fantasma se producen cuando el tambor no se limpia o descarga correctamente, a menudo por un tambor o cuchilla de limpieza desgastados. El texto ilegible apunta a los drivers.", ["Un driver incorrecto causa símbolos ilegibles, no una repetición tenue de una imagen anterior en la página.", null, "Los rodillos de alimentación gastados causan atascos y alimentaciones incorrectas, no imágenes fantasma repetidas.", "El poco tóner hace que toda la impresión se vea tenue, no una segunda copia de una imagen anterior más abajo en la página."]],
  "ap86": ["Los trabajos de impresión de los usuarios se quedan atorados en la cola de impresión de Windows y los nuevos trabajos se acumulan detrás. ¿Qué debe intentar el técnico PRIMERO?", ["Reemplazar el fusor de la impresora", "Vaciar la cola y reiniciar el spooler", "Instalar un nuevo cartucho de tóner", "Cambiar la configuración de la bandeja de papel"], "Detener el servicio Print Spooler, eliminar los trabajos atorados y reiniciarlo a menudo libera una cola bloqueada. Las piezas de hardware no son la causa.", ["El fusor afecta cómo se adhiere el tóner al papel; no puede hacer que los trabajos se atoren en la cola de impresión de Windows.", null, "El poco tóner produce páginas desvanecidas, pero no impide que los trabajos salgan de la cola.", "La configuración de la bandeja puede causar avisos de tamaño de papel, pero no congelaría el spooler de Windows ni acumularía trabajos."]],
  "ap87": ["Una impresora imprime páginas llenas de símbolos aleatorios después de ser reemplazada por otro modelo. ¿Cuál es la causa MÁS probable?", ["El tóner está bajo", "El fusor se está sobrecalentando", "Todavía se usa el driver del modelo anterior", "Los rodillos de recogida de la impresora están sucios"], "La salida ilegible suele deberse a un driver incorrecto o dañado que envía el lenguaje de descripción de página equivocado. El poco tóner causa impresión desvanecida.", ["El poco tóner produce impresión desvanecida o clara, no símbolos aleatorios.", "Un fusor sobrecalentado causa manchas o códigos de error, no páginas de caracteres ilegibles.", null, "Los rodillos de recogida sucios causan alimentaciones incorrectas y atascos, no contenido ilegible en la página."]],
  "ap88": ["Una laptop indica 'Sin internet' e ipconfig muestra 169.254.33.10. ¿Qué indica esta dirección?", ["La PC tiene una dirección pública válida", "La resolución DNS funciona normalmente", "El gateway es un servidor Linux", "La PC no pudo obtener un lease DHCP"], "169.254.x.x es una dirección APIPA, asignada cuando ningún servidor DHCP responde. Hay que revisar el cable o el enlace Wi-Fi, el servidor DHCP y el scope.", ["169.254.x.x es un rango APIPA link-local y nunca es una dirección pública válida de internet.", "La dirección muestra que la PC nunca obtuvo la configuración DHCP, así que probablemente no tiene ninguna configuración de servidor DNS.", "Una dirección APIPA no dice nada sobre el sistema operativo del gateway; la PC nunca recibió un gateway por DHCP.", null]],
  "ap89": ["El Wi-Fi de la cocina de una oficina se cae cada vez que funciona el microondas. ¿Cuál es la MEJOR solución?", ["Reducir el tiempo de lease DHCP del router", "Cambiar el servidor DNS por uno público", "Ocultar el SSID", "Mover los clientes a la banda de 5 GHz"], "Los hornos de microondas emiten alrededor de 2.4 GHz e interfieren con esa banda. La banda de 5 GHz evita esta interferencia.", ["El tiempo de lease controla cuánto tiempo se asigna una dirección IP y no afecta la interferencia de radio.", "Cambiar los servidores DNS afecta la resolución de nombres, no la interferencia en 2.4 GHz que tumba el enlace inalámbrico.", "Ocultar el SSID solo evita que se transmita; la red sigue usando la misma frecuencia con interferencia.", null]],
  "ap90": ["La conexión cableada de un usuario funciona, pero es mucho más lenta de lo esperado, y la NIC muestra un enlace de 100 Mbps en un switch gigabit. ¿Qué debe revisar el técnico PRIMERO?", ["Las extensiones del navegador del usuario", "La lista de búsqueda de sufijos DNS", "El patch cord por si tiene un par dañado", "La dirección IP de la impresora"], "Gigabit Ethernet necesita los cuatro pares; un par dañado a menudo obliga al enlace a bajar a 100 Mbps. Hay que probar o reemplazar el patch cord.", ["Las extensiones del navegador pueden hacer lentas las páginas web, pero no pueden obligar a la NIC a negociar un enlace de 100 Mbps.", "La lista de búsqueda de sufijos DNS afecta cómo se resuelven los nombres cortos, no la velocidad del enlace físico.", null, "La dirección IP de la impresora no tiene nada que ver con la velocidad de enlace de la NIC del usuario."]],
  "x1": ["Un empleado de finanzas edita hojas de cálculo en una laptop durante sus trayectos en tren y le preocupa que los pasajeros cercanos puedan leer la pantalla. ¿Qué accesorio resuelve esto MEJOR?", ["Un filtro de privacidad para la pantalla", "Un protector antirreflejo mate", "Un candado de cable para laptop", "Una pantalla de reemplazo más brillante"], "Un filtro de privacidad reduce el ángulo de visión para que solo la persona que está justo enfrente pueda leer la pantalla. Un protector antirreflejo reduce los reflejos, pero la pantalla sigue siendo legible desde un costado.", [null, "Los recubrimientos antirreflejo reducen los reflejos, pero la pantalla sigue siendo legible desde un costado.", "Un candado de cable evita el robo de la laptop, no que la gente lea la pantalla.", "Una pantalla más brillante hace que a los vecinos les sea más fácil leerla, no más difícil."]],
  "x2": ["Un viajero quiere agregar el plan de datos de un operador local mientras está en el extranjero sin abrir la bandeja de la SIM. El teléfono lo admite. ¿Qué debe hacer el usuario?", ["Activar el modo avión y volver a conectarse al Wi-Fi", "Instalar un perfil eSIM del operador", "Tocar el teléfono en un kiosco NFC", "Emparejarse con el teléfono de un amigo local mediante tethering Bluetooth"], "Una eSIM es una SIM integrada que puede cargarse con un perfil del operador, a menudo desde un código QR, sin tarjeta física. El modo avión apaga los radios y no agrega un plan de operador.", ["El modo avión apaga los radios; no agrega un plan de operador.", null, "NFC sirve para pagos y emparejamientos de corto alcance, no para agregar planes de operador.", "El emparejamiento Bluetooth no le da al teléfono su propio plan de un operador local."]],
  "x3": ["En un vuelo, un pasajero debe apagar el radio celular del teléfono, pero aún quiere usar el Wi-Fi a bordo y sus audífonos Bluetooth. ¿Qué debe hacer?", ["Apagar el teléfono durante el vuelo", "Desactivar solo los servicios de ubicación", "Usar el modo avión y luego volver a activar Wi-Fi y Bluetooth", "Sacar la tarjeta SIM del teléfono"], "El modo avión desactiva todos los radios, y luego se pueden volver a activar el Wi-Fi y el Bluetooth mientras el celular permanece apagado. Desactivar los servicios de ubicación deja funcionando el radio celular.", ["Apagar el teléfono también elimina el Wi-Fi y el Bluetooth, que el usuario quiere conservar.", "Los servicios de ubicación son independientes; el radio celular seguiría encendido.", null, "Sacar la SIM no apaga todas las funciones del radio celular y es poco práctico."]],
  "x4": ["Los empleados usan sus teléfonos personales para el correo de la empresa, pero se niegan a que TI controle todo el dispositivo. La empresa debe poder borrar solo los datos corporativos si se pierde un teléfono. ¿Qué es lo MÁS adecuado?", ["Un borrado completo del dispositivo mediante MDM", "Una política de restablecimiento de fábrica para teléfonos perdidos", "Una regla de bloqueo de pantalla para cada aplicación personal", "Administración de aplicaciones (MAM) de las apps de la empresa"], "La administración de aplicaciones móviles controla y puede borrar solo las apps administradas de la empresa y sus datos, sin tocar el contenido personal. Un borrado completo por MDM también eliminaría los datos personales del empleado.", ["Un borrado completo por MDM también elimina los datos personales del empleado.", "Un restablecimiento de fábrica también borra los datos personales, algo que los empleados rechazan.", "Un bloqueo de pantalla protege el acceso, pero no puede eliminar datos de la empresa de forma remota.", null]],
  "x5": ["Después de reemplazar el conjunto de pantalla de una laptop, la webcam y el micrófono integrado dejan de funcionar, aunque la imagen se ve bien. ¿Qué se omitió MÁS probablemente?", ["El cable de la webcam/micrófono en el marco de la pantalla", "La actualización del driver de la tarjeta Wi-Fi", "El cable plano del teclado", "El conector de la batería CMOS"], "La webcam y a menudo los micrófonos están en el marco de la pantalla y usan su propio cable, que debe volver a conectarse. El driver de la tarjeta Wi-Fi no tiene nada que ver con la cámara, aunque las antenas también pasen por la tapa.", [null, "El driver Wi-Fi no tiene nada que ver con la cámara ni con el micrófono.", "El cable del teclado está en la base y no da servicio al marco de la pantalla.", "La batería CMOS mantiene la configuración del firmware y la hora, no el funcionamiento de la cámara."]],
  "x6": ["Un usuario borró su teléfono anterior después de cambiarse a uno nuevo y ahora no puede obtener códigos de la aplicación de autenticación de la empresa. ¿Qué debió hacer antes de borrar el teléfono anterior?", ["Respaldar las fotos en el almacenamiento en la nube", "Transferir o volver a inscribir las cuentas del autenticador", "Desactivar primero Bluetooth y Wi-Fi en el teléfono anterior", "Copiar los contactos guardados en la SIM"], "Las cuentas del autenticador deben transferirse o volver a inscribirse en el nuevo dispositivo antes de borrar el anterior. Un respaldo de fotos no transfiere los secretos que generan los códigos.", ["Los respaldos de fotos no incluyen los secretos que generan los códigos.", null, "La configuración de Bluetooth no interviene en los códigos del autenticador.", "Los contactos de la SIM no contienen las cuentas del autenticador."]],
  "x7": ["Una laptop tiene un sensor de huellas integrado. Los usuarios quieren iniciar sesión rápidamente sin escribir una contraseña donde otros puedan verla. ¿Qué opción es adecuada?", ["Un patrón de desbloqueo en la pantalla de bloqueo", "Un filtro de privacidad sobre la pantalla", "Inicio de sesión biométrico con huella", "Un tiempo de espera de pantalla de un minuto"], "Registrar una huella permite a los usuarios iniciar sesión con el sensor biométrico en lugar de escribir una contraseña. Un filtro de privacidad oculta la pantalla, pero no cambia la forma de iniciar sesión.", ["Un patrón sigue siendo algo que otros pueden ver mientras se ingresa.", "Un filtro de privacidad oculta la pantalla, pero no cambia la forma en que los usuarios inician sesión.", null, "Un tiempo de espera bloquea la laptop antes, pero igual se necesita una contraseña para iniciar sesión."]],
  "x8": ["Una laptop antigua tiene una bahía para disco SATA de 2.5 pulgadas y no tiene ranura M.2. El usuario quiere tiempos de arranque mucho más rápidos. ¿Cuál es la MEJOR mejora?", ["Un SSD M.2 NVMe con un adaptador", "Un disco duro de 3.5 pulgadas a 7200 RPM", "Una memoria USB como dispositivo de arranque", "Un SSD SATA de 2.5 pulgadas"], "Un SSD SATA de 2.5 pulgadas cabe en la bahía existente y es mucho más rápido que un disco duro. Una unidad M.2 NVMe necesita una ranura M.2 con PCIe, que esta laptop no tiene.", ["La laptop no tiene ranura M.2, así que no se puede usar una unidad NVMe.", "Un disco de escritorio de 3.5 pulgadas no cabe en una bahía de laptop y es más lento que un SSD.", "Arrancar desde una memoria USB es lento y poco confiable para un disco de sistema de uso diario.", null]],
  "x9": ["Un firewall se encuentra entre las PC cliente y el servidor DHCP. ¿Qué tráfico debe permitirse para que los clientes obtengan direcciones?", ["UDP 67 y 68", "TCP 67 y 68", "UDP 161 y 162", "TCP 20 y 21"], "DHCP usa UDP, con el servidor en el puerto 67 y el cliente en el puerto 68. TCP 67 y 68 es incorrecto porque DHCP nunca usa TCP.", [null, "DHCP funciona sobre UDP, no TCP, en estos puertos.", "UDP 161 y 162 son el sondeo y los traps de SNMP, no DHCP.", "TCP 20 y 21 son los canales de datos y control de FTP, no DHCP."]],
  "x10": ["Un sistema de monitoreo consulta los contadores de interfaz de los switches y recibe las alertas que los switches envían cuando un enlace se cae. ¿Qué protocolo hace esto?", ["LDAP en TCP 389", "SNMP en UDP 161 y 162", "Telnet en TCP 23", "SMB en TCP 445"], "SNMP consulta los dispositivos en UDP 161 y recibe traps en UDP 162. LDAP consulta servicios de directorio como Active Directory y no recopila estadísticas de dispositivos.", ["LDAP sirve para consultas de directorio como cuentas de usuario, no para contadores de dispositivos.", null, "Telnet es una línea de comandos remota y no recopila estadísticas ni traps.", "SMB es el uso compartido de archivos de Windows y no interviene en el monitoreo de dispositivos."]],
  "x11": ["Un switch antiguo se administra con un protocolo que envía las contraseñas en texto claro por el puerto 23. ¿Qué debe reemplazarlo para una administración segura por línea de comandos?", ["RDP en el puerto 3389", "HTTP en el puerto 80", "SSH en el puerto 22", "FTP en el puerto 21"], "SSH en el puerto 22 ofrece una sesión de línea de comandos cifrada y reemplaza a Telnet en el puerto 23. RDP ofrece un escritorio gráfico de Windows, no la línea de comandos de un switch.", ["RDP proporciona un escritorio gráfico de Windows, no acceso por línea de comandos al switch.", "HTTP es tráfico web sin cifrar, así que las contraseñas seguirían expuestas.", null, "FTP transfiere archivos y también envía las contraseñas en texto claro."]],
  "x12": ["Un usuario lee el correo en un teléfono y una laptop y quiere que el estado de leído y las carpetas coincidan en ambos, con el correo guardado en el servidor. ¿Qué protocolo debe usar el cliente de correo?", ["POP3 en el puerto 110", "SMTP en el puerto 25", "LDAP en el puerto 389", "IMAP en el puerto 143"], "IMAP mantiene el correo y las carpetas en el servidor, así que todos los dispositivos ven el mismo estado. POP3 normalmente descarga el correo a un solo dispositivo, por lo que el teléfono y la laptop dejan de coincidir.", ["POP3 normalmente descarga el correo a un solo dispositivo, así que ambos dispositivos dejan de coincidir.", "SMTP envía correo entre servidores; no sincroniza buzones con los clientes.", "LDAP es un protocolo de directorio, no una forma de leer el correo.", null]],
  "x13": ["¿Qué tipo de registro DNS asigna un nombre de host a una dirección IPv6?", ["AAAA", "A", "MX", "CNAME"], "Un registro AAAA asigna un nombre a una dirección IPv6 de 128 bits. Un registro A hace lo mismo, pero solo para direcciones IPv4.", [null, "Un registro A asigna un nombre a una dirección IPv4, no IPv6.", "Un registro MX indica los servidores de correo de un dominio.", "Un CNAME apunta un nombre a otro nombre, no a una dirección."]],
  "x14": ["Una empresa ya publica SPF y firma su correo con DKIM. Ahora quiere indicar a los servidores receptores qué hacer con el correo que no pasa estas verificaciones y que le envíen informes. ¿Qué registro debe agregar?", ["Un registro MX para un servidor de respaldo", "Una política DMARC en un registro TXT", "Un CNAME que apunte al host de correo", "Un registro AAAA para el servidor de correo"], "DMARC, publicado como registro TXT, indica a los receptores cómo tratar el correo que falla la alineación de SPF y DKIM y a dónde enviar los informes. Un registro MX solo indica qué servidores aceptan el correo del dominio.", ["Los registros MX solo indican qué servidores aceptan el correo del dominio.", null, "Un CNAME es un alias y no puede contener una política de manejo de correo.", "Un registro AAAA da una dirección IPv6 y no dice nada sobre el correo que falla."]],
  "x15": ["Una casa recibe servicio de fibra hasta el hogar (FTTP). ¿Qué dispositivo en la casa convierte la señal óptica para el router del cliente?", ["Un cable módem", "Un módem DSL", "Un terminal de red óptica (ONT)", "Un inyector PoE"], "Un ONT termina la fibra y entrega Ethernet al router. Un cable módem funciona con el servicio de cable coaxial, no con fibra.", ["Un cable módem funciona con el servicio de cable coaxial, no con fibra.", "Un módem DSL funciona sobre líneas telefónicas, no con fibra.", null, "Un inyector PoE agrega energía a Ethernet; no termina la fibra."]],
  "x16": ["Una oficina compra access points Wi-Fi 6E para alejarse de los canales saturados. ¿Qué banda agrega 6E?", ["2.4 GHz", "900 MHz", "60 GHz", "6 GHz"], "Wi-Fi 6E extiende 802.11ax a la banda de 6 GHz, que tiene muchos canales limpios. 2.4 GHz es la banda antigua y saturada que la oficina quiere evitar.", ["2.4 GHz es la banda antigua y saturada que la oficina quiere evitar.", "900 MHz no es una banda de Wi-Fi 6E.", "60 GHz la usa otro estándar de corto alcance, no Wi-Fi 6E.", null]],
  "x17": ["Una revisión de seguridad descubre que una consola de videojuegos abrió por sí sola puertos entrantes en un router SOHO. ¿Qué función del router lo permitió y por qué es un riesgo?", ["UPnP, porque cualquier dispositivo puede abrir puertos sin aprobación del administrador", "DMZ, porque oculta todos los dispositivos detrás del NAT del router", "WPA3, porque permite a los clientes cambiar la configuración del router", "La reserva DHCP, porque abre un puerto por cada MAC"], "UPnP permite que los dispositivos, y cualquier malware que tengan, abran reenvíos de puertos automáticamente sin que el administrador lo sepa. Una DMZ expone un host de forma deliberada; no permite que los dispositivos abran sus propios puertos.", [null, "Una DMZ expone un host elegido; no permite que los dispositivos abran sus propios puertos.", "WPA3 es cifrado Wi-Fi y no permite a los clientes cambiar la configuración del router.", "Una reserva DHCP fija una dirección IP y no abre ningún puerto."]],
  "x18": ["¿Qué ocurre cuando la configuración DMZ de un router SOHO apunta a una PC interna?", ["Se bloquea todo el tráfico entrante hacia esa PC", "El tráfico entrante no solicitado se envía a esa PC", "Se crea una red Wi-Fi de invitados separada para los visitantes", "Cada dispositivo recibe su propia IP pública"], "Un host DMZ de un router SOHO recibe todo el tráfico entrante no solicitado que no coincide con otra regla, lo que expone esa PC. No bloquea tráfico; es lo contrario de una protección.", ["Un host DMZ queda expuesto al tráfico entrante, lo contrario de bloquearlo.", null, "El Wi-Fi de invitados es una función aparte y no la crea la configuración DMZ.", "El router sigue teniendo una sola IP pública; los dispositivos no reciben una cada uno."]],
  "x19": ["ipconfig muestra que la dirección IPv6 de una PC comienza con fe80::. ¿Qué tipo de dirección es?", ["Una dirección global unicast", "Una dirección multicast", "Una dirección link-local", "La dirección de loopback"], "Las direcciones fe80:: son link-local; toda interfaz IPv6 tiene una y no se enrutan más allá del enlace local. La dirección de loopback de IPv6 es ::1, no una dirección fe80::.", ["Las direcciones global unicast son enrutables y normalmente comienzan con 2 o 3, no con fe80.", "Las direcciones multicast de IPv6 comienzan con ff, no con fe80.", null, "La dirección de loopback de IPv6 es ::1."]],
  "x20": ["Una tienda en línea tiene tres servidores web idénticos y quiere repartir las solicitudes entre ellos, desviando el tráfico de cualquier servidor que falle. ¿Qué dispositivo es adecuado?", ["Un servidor proxy", "Un gateway antispam", "Un servidor syslog", "Un balanceador de carga"], "Un balanceador de carga reparte las solicitudes de los clientes entre los servidores y deja de enviar a uno que no pasa sus verificaciones de estado. Un servidor proxy actúa en nombre de los clientes hacia afuera, con caché y filtrado, en lugar de repartir la carga entre servidores.", ["Un proxy actúa en nombre de los clientes hacia afuera; no reparte la carga entre servidores.", "Un gateway antispam filtra correo, no solicitudes web.", "Un servidor syslog recopila registros y no maneja solicitudes de clientes.", null]],
  "x21": ["El administrador de red quiere que routers, firewalls y servidores envíen sus mensajes de registro a un lugar central para revisarlos. ¿Qué debe configurarse?", ["Un servidor syslog", "Un servidor AAA", "Un servidor DHCP", "Un servidor de archivos"], "Un servidor syslog recopila en un solo lugar los mensajes de registro que envían muchos dispositivos. Un servidor AAA maneja la autenticación y la contabilidad, no los registros generales de los dispositivos.", [null, "Un servidor AAA maneja la autenticación y la contabilidad, no los registros de los dispositivos.", "Un servidor DHCP entrega direcciones y no recopila registros.", "Un servidor de archivos almacena archivos compartidos y no está hecho para recibir mensajes de registro."]],
  "x22": ["Un técnico sospecha que el puerto de red de una PC está dañado y quiere probarlo sin switch ni red conectados. ¿Qué herramienta ayuda?", ["Un generador de tonos y sonda", "Un conector loopback", "Un analizador Wi-Fi", "Una herramienta punchdown"], "Un conector loopback devuelve la señal de transmisión del puerto a sus pines de recepción para que el puerto se pruebe a sí mismo. Un generador de tonos y sonda rastrea tendidos de cable, pero no prueba un puerto de red.", ["Un generador de tonos y sonda rastrea tendidos de cable; no prueba un puerto.", null, "Un analizador Wi-Fi revisa señales inalámbricas, no un puerto cableado.", "Una herramienta punchdown termina cables en un bloque; no prueba nada."]],
  "x23": ["Un técnico termina un extremo de un patch cord como T568A y el otro como T568B. ¿Qué tipo de cable resulta?", ["Un cable directo (straight-through)", "Un cable rollover", "Un cable cruzado (crossover)", "Un cable plenum"], "Cablear un extremo como A y el otro como B intercambia los pares de transmisión y recepción, formando un cable cruzado. Un cable directo usa el mismo estándar en ambos extremos.", ["Un cable directo usa el mismo estándar en ambos extremos.", "Un cable rollover invierte todos los pines y se usa para conexiones de consola.", null, "Plenum describe la clasificación contra incendios de la cubierta, no el cableado de los pines."]],
  "x24": ["Un enlace de red debe recorrer 400 metros entre dos edificios, a través de una zona con fuerte interferencia eléctrica. ¿Qué cable es el MÁS adecuado?", ["Par trenzado sin blindaje Cat 6", "Par trenzado blindado Cat 5e", "Cable coaxial RG-6", "Cable de fibra óptica"], "La fibra transporta luz, así que es inmune a la interferencia eléctrica y cubre distancias mucho mayores que el cobre. El Cat 5e blindado ayuda con la interferencia, pero sigue limitado a unos 100 metros para Ethernet.", ["El cobre sin blindaje sufre interferencia y está limitado a unos 100 m.", "El blindaje ayuda con el ruido, pero el Ethernet de cobre sigue llegando solo a unos 100 m.", "El coaxial no se usa para este tipo de enlace Ethernet entre edificios.", null]],
  "x25": ["Un usuario compra un SSD M.2 NVMe para una laptop cuya ranura M.2 solo admite unidades SATA. ¿Qué ocurrirá?", ["La unidad no funcionará, ya que la ranura no admite NVMe", "La unidad funciona a velocidad NVMe completa en la ranura", "La unidad vuelve por sí sola a la velocidad SATA", "La unidad funcionará una vez que se instale un nuevo driver del chipset"], "Una unidad NVMe necesita carriles PCIe, así que una ranura M.2 solo SATA no puede usarla aunque quepa. Las unidades NVMe no vuelven a modo SATA; el conector es compartido, pero la interfaz no.", [null, "La ranura no tiene carriles PCIe, así que la velocidad NVMe no es posible.", "Las unidades NVMe no tienen un modo de respaldo SATA.", "Ningún driver puede agregar carriles PCIe que la ranura no tiene."]],
  "x26": ["Un arreglo de seis discos debe seguir funcionando después de que fallen CUALESQUIERA dos discos al mismo tiempo. ¿Qué nivel de RAID es el MÁS adecuado?", ["RAID 5", "RAID 6", "RAID 10", "RAID 1 con dos discos"], "RAID 6 almacena dos conjuntos de paridad, así que pueden fallar cualesquiera dos discos. RAID 10 sobrevive a dos fallas solo si están en pares de espejo diferentes, no cualesquiera dos discos.", ["RAID 5 tiene un conjunto de paridad y solo sobrevive a la falla de un disco.", null, "RAID 10 falla si fallan ambos discos de un mismo par en espejo.", "Un espejo de dos discos no usa seis discos y no puede perder ambos discos."]],
  "x27": ["El puerto USB-C de una laptop tiene un pequeño símbolo de rayo al lado. ¿Qué indica esto normalmente?", ["Es un puerto solo de carga", "Es un puerto Lightning", "Admite Thunderbolt", "Solo emite video VGA"], "Un rayo junto a un puerto USB-C indica compatibilidad con Thunderbolt, que transporta datos rápidos, pantallas y docks. Lightning es el conector propio de Apple en iPhones antiguos, no un puerto USB-C.", ["En un puerto USB-C el rayo indica compatibilidad con Thunderbolt, no un puerto limitado a la carga.", "Lightning es el conector propio de Apple, no un puerto USB-C.", null, "Los puertos USB-C no emiten VGA; VGA necesita un adaptador."]],
  "x28": ["Una empresa necesita hardware dedicado y resistente a manipulaciones para crear y almacenar muchas claves de cifrado que usa un grupo de servidores web. ¿Qué debe comprar?", ["Un chip TPM en la placa de cada servidor web", "Secure Boot activado en UEFI", "Una contraseña de BIOS en cada servidor", "Un módulo de seguridad de hardware (HSM)"], "Un HSM es un dispositivo dedicado diseñado para generar, almacenar y usar muchas claves de forma segura para servidores. Un TPM está ligado a una sola máquina y está pensado para proteger ese sistema.", ["Un TPM protege una máquina; no es un almacén de claves compartido para muchos servidores.", "Secure Boot verifica las firmas del software de arranque; no almacena claves para servidores.", "Una contraseña de BIOS bloquea los cambios de firmware y no tiene nada que ver con el almacenamiento de claves.", null]],
  "x29": ["Los usuarios cambian constantemente el orden de arranque para iniciar las PC del laboratorio desde sus propias memorias USB. ¿Qué impide esto de forma MÁS directa?", ["Una contraseña de supervisor del firmware", "Habilitar el TPM en el firmware", "Deshabilitar Secure Boot", "Una contraseña del protector de pantalla de Windows"], "Una contraseña de supervisor de UEFI/BIOS impide que los usuarios cambien configuraciones del firmware, como el orden de arranque. Una contraseña de Windows no sirve de nada una vez que alguien llega a la configuración del firmware.", [null, "El TPM almacena claves; no bloquea el orden de arranque.", "Desactivar Secure Boot haría más fácil arrancar desde otros medios, no más difícil.", "Una contraseña de Windows no protege la configuración del firmware."]],
  "x30": ["Una empresa está evaluando laptops delgadas con procesadores ARM en lugar de x86. ¿Qué es lo principal que debe verificar PRIMERO?", ["Si los chips ARM pueden ejecutar cualquier sistema operativo", "Si sus aplicaciones x86 tienen versiones para ARM o funcionan bien emuladas", "Si las laptops ARM siempre necesitan refrigeración líquida para funcionar con seguridad", "Si los procesadores ARM se venden con gráficos integrados"], "ARM usa un conjunto de instrucciones diferente, así que el software solo x86 necesita una versión ARM o emulación, que puede ser más lenta o no estar soportada. Los chips ARM sí ejecutan sistemas operativos completos, así que eso no es lo preocupante.", ["Los procesadores ARM sí ejecutan sistemas operativos completos, incluidos Windows y Linux.", null, "Las laptops ARM son conocidas por su bajo consumo y normalmente necesitan poca refrigeración.", "La mayoría de los chips ARM para laptop sí incluyen gráficos integrados."]],
  "x31": ["Una CPU se anuncia con 8 núcleos y 16 hilos. ¿Qué proporciona los 16 hilos?", ["Dos encapsulados de CPU físicos", "Su unidad de gráficos integrada", "Dos hilos por núcleo (SMT)", "Memoria en dual channel"], "El multihilo simultáneo, como Intel Hyper-Threading, permite que cada núcleo ejecute dos hilos a la vez. Es un solo encapsulado de CPU, no dos; ocho núcleos por dos hilos dan 16.", ["Es un solo encapsulado de CPU; los ocho núcleos están en ese único chip.", "Los gráficos integrados manejan la salida de video, no hilos adicionales de CPU.", null, "Los canales de memoria afectan el ancho de banda, no cuántos hilos ejecuta la CPU."]],
  "x32": ["Un streamer quiere grabar en una PC de escritorio el juego desde la salida HDMI de una consola. ¿Qué tarjeta de expansión necesita?", ["Una tarjeta de sonido", "Una tarjeta de interfaz de red", "Una tarjeta gráfica con más VRAM", "Una tarjeta capturadora de video"], "Una capturadora recibe una entrada de video HDMI y la pone a disposición del software de grabación. Una tarjeta gráfica envía video desde la PC; no acepta video de otro dispositivo.", ["Una tarjeta de sonido maneja audio y no puede recibir video HDMI.", "Una NIC se conecta a redes y no acepta entrada de video.", "Una tarjeta gráfica envía video hacia afuera; no captura la salida de una consola.", null]],
  "x33": ["Un usuario se muda con su PC de escritorio de Estados Unidos a Europa. La etiqueta de la PSU dice entrada autoajustable de 100-240 V. ¿Qué se necesita?", ["Solo un cable de alimentación para el tomacorriente local", "Una nueva PSU clasificada para 240 V", "Un transformador elevador", "Un interruptor configurado para salida de 220 V"], "Una PSU autoajustable acepta cualquier entrada de 100 a 240 V, así que solo se necesita el cable o enchufe correcto. Un transformador solo es necesario para dispositivos de voltaje fijo, y esta PSU no lo es.", [null, "No se necesita una PSU nueva, ya que la actual ya acepta 240 V.", "Los transformadores son para dispositivos de voltaje fijo; esta PSU es autoajustable.", "Las salidas de la PSU son voltajes bajos de CC; no existe un interruptor de salida de 220 V."]],
  "x34": ["Un armador de PC quiere reducir el desorden de cables conectando solo los cables de alimentación que el equipo realmente necesita. ¿Qué tipo de PSU es adecuada?", ["Una PSU redundante", "Una PSU modular", "Una PSU de mayor potencia", "Una PSU de doble riel"], "Las PSU modulares tienen cables desmontables, así que los que no se usan pueden dejarse fuera. Una PSU redundante agrega una segunda fuente para mayor disponibilidad y no ayuda con el desorden de cables.", ["Una PSU redundante agrega una fuente de respaldo; no reduce los cables.", null, "Más potencia no cambia cuántos cables están conectados.", "El diseño de rieles afecta la entrega de energía, no si los cables pueden retirarse."]],
  "x35": ["Quedan documentos confidenciales en la bandeja de salida de una impresora compartida. ¿Qué función retiene cada trabajo hasta que el usuario ingresa un PIN en la impresora?", ["Impresión dúplex", "Intercalado", "Impresión segura", "Asignación de bandeja"], "La impresión segura retiene los trabajos hasta que el usuario se autentica en el dispositivo, así las páginas no quedan expuestas. El intercalado solo ordena las páginas en trabajos de varias copias.", ["El dúplex imprime por ambos lados y no retiene trabajos.", "El intercalado ordena las páginas en trabajos de varias copias; no las retiene.", null, "La asignación de bandeja elige la fuente de papel, no cuándo se libera un trabajo."]],
  "x36": ["¿Qué consumible usa una impresora 3D de escritorio típica que construye piezas capa por capa a partir de plástico derretido?", ["Tóner en polvo", "Una cinta de tinta", "Papel térmico", "Filamento plástico"], "Las impresoras 3D de filamento fundido derriten filamento plástico y lo depositan en capas. El tóner es el polvo que usan las impresoras láser, no las impresoras 3D.", ["El tóner es el polvo que usan las impresoras láser.", "Las cintas de tinta las usan las impresoras de impacto.", "El papel térmico lo usan las impresoras térmicas de recibos.", null]],
  "x37": ["Una oficina quiere una impresora que todas las PC puedan usar incluso cuando la PC de un usuario en particular esté apagada. ¿Cuál es la MEJOR configuración?", ["Darle su propia conexión de red y una IP fija", "Compartirla desde la PC de escritorio de un usuario", "Mover su cable USB de una PC a otra", "Emparejarla con cada PC por Bluetooth"], "Una impresora de red con dirección fija o reserva funciona para todos sin depender de una PC anfitriona. Compartirla desde un escritorio falla cada vez que ese escritorio está apagado.", [null, "Compartirla desde un escritorio falla cada vez que esa PC está apagada.", "Mover el cable entre PC es poco práctico y solo una PC puede imprimir a la vez.", "El emparejamiento Bluetooth es de corto alcance y no es adecuado para una impresora compartida de oficina."]],
  "x38": ["Una VM de prueba debe aparecer en la LAN de la oficina con su propia dirección del servidor DHCP de la oficina para que otras PC puedan alcanzarla. ¿Qué modo de red de la VM es adecuado?", ["NAT", "Bridged", "Red interna", "Sin adaptador de red"], "El modo bridged conecta la VM directamente a la red física, así que obtiene una dirección de la LAN como cualquier otra PC. NAT oculta la VM detrás de la dirección del anfitrión, por lo que otras PC no pueden alcanzarla fácilmente.", ["NAT oculta la VM detrás del anfitrión, así que otras PC no pueden alcanzarla fácilmente.", null, "Una red interna aísla la VM por completo de la LAN.", "Sin un adaptador de red, la VM no tiene ningún acceso a la red."]],
  "x39": ["Dos VM de laboratorio usadas para capacitación sobre malware deben comunicarse entre sí, pero no deben llegar a la LAN del anfitrión ni a internet. ¿Qué configuración de red de la VM es adecuada?", ["Bridged al adaptador del anfitrión", "NAT a través del anfitrión", "Una red interna", "Carpetas compartidas con el anfitrión"], "Una red interna conecta las VM solo entre sí, sin camino hacia la LAN ni internet. NAT seguiría permitiendo que las VM lleguen a redes externas a través del anfitrión.", ["El modo bridged pone las VM en la LAN, lo cual debe evitarse.", "NAT sigue permitiendo que las VM lleguen a redes externas a través del anfitrión.", null, "Las carpetas compartidas conectan las VM con archivos del anfitrión, lo que no las aísla."]],
  "x40": ["Antes de aplicar una actualización riesgosa dentro de una VM de prueba, un técnico quiere una forma rápida de volver al estado actual. ¿Qué debe hacer?", ["Clonar el disco físico del anfitrión", "Agregar más RAM a la VM", "Activar la virtualización anidada", "Tomar un snapshot de la VM"], "Un snapshot guarda el estado de la VM para poder revertirlo rápidamente si la actualización rompe algo. Clonar el disco del anfitrión es lento y no es necesario para revertir una sola VM.", ["Clonar el disco del anfitrión es lento e innecesario para revertir una sola VM.", "Más RAM no da ninguna forma de deshacer la actualización.", "La virtualización anidada ejecuta hipervisores dentro de VM y no tiene nada que ver con revertir cambios.", null]],
  "x41": ["Un gerente dice que las VM de un servidor están seguras porque el sistema operativo anfitrión tiene todos los parches. ¿Es correcto?", ["No, cada sistema operativo invitado igual debe recibir parches", "Sí, las VM heredan los parches del anfitrión", "Sí, el hipervisor bloquea todo el malware de los invitados", "No, pero solo los invitados de Tipo 2 necesitan parches"], "Cada invitado tiene su propio sistema operativo y aplicaciones, que necesitan sus propias actualizaciones. Los invitados no heredan los parches del anfitrión; el anfitrión y los invitados se parchean por separado.", [null, "Los invitados ejecutan sus propios sistemas operativos y no heredan los parches del anfitrión.", "Los hipervisores aíslan las VM, pero no analizan ni bloquean el malware en los invitados.", "Tanto los invitados de Tipo 1 como los de Tipo 2 necesitan sus propios parches."]],
  "x42": ["Los desarrolladores quieren desplegar su código web sin administrar servidores, sistemas operativos ni parches del runtime. ¿Qué modelo de servicio en la nube es adecuado?", ["Máquinas virtuales IaaS", "Platform as a service", "Un centro de datos privado", "Desktop as a service"], "PaaS ofrece una plataforma administrada donde los desarrolladores despliegan código mientras el proveedor se encarga del sistema operativo y el runtime. Con IaaS el cliente sigue parcheando y administrando el sistema operativo.", ["IaaS sigue dejando al cliente los parches del sistema operativo y del runtime.", null, "Un centro de datos privado significa que la empresa administra todos los servidores por su cuenta.", "DaaS entrega escritorios a los usuarios, no una plataforma para desplegar código."]],
  "x43": ["Varios hospitales comparten infraestructura en la nube diseñada para sus necesidades comunes de privacidad y cumplimiento, y nadie más la usa. ¿Qué modelo de implementación es este?", ["Nube pública", "Nube híbrida", "Nube comunitaria", "Una nube privada para cada uno"], "Una nube comunitaria la comparten organizaciones con requisitos comunes, como las normas de salud. Una nube pública está abierta a cualquier cliente, no limitada a un grupo.", ["Una nube pública está abierta a cualquier cliente, no limitada a un grupo.", "La híbrida combina nubes privadas y públicas; no describe el uso compartido por un grupo.", null, "Nubes privadas separadas no serían compartidas entre los hospitales."]],
  "x44": ["Un anfitrión con 16 GB de RAM ejecuta un hipervisor Tipo 2. A tres VM se les asignan 6 GB a cada una, y la última no inicia o todo funciona muy lento. ¿Cuál es la causa MÁS probable?", ["Los sistemas operativos invitados son demasiado nuevos", "La red NAT está haciendo más lento el acceso a memoria de cada VM", "Los hipervisores Tipo 2 no pueden ejecutar tres VM", "La RAM de las VM más las necesidades del anfitrión superan los 16 GB"], "Tres VM de 6 GB necesitan 18 GB antes de que el sistema operativo anfitrión tome su parte, lo que supera lo instalado. Los hipervisores Tipo 2 pueden ejecutar varias VM; el límite aquí es la memoria, no el tipo de hipervisor.", ["Las versiones más nuevas de los sistemas invitados no hacen que el anfitrión se quede sin memoria.", "La red NAT afecta el tráfico, no cuánta RAM usan las VM.", "Los hipervisores Tipo 2 pueden ejecutar varias VM; el límite aquí es la memoria.", null]],
  "x45": ["Después de reemplazar una NIC dañada, un técnico confirma que el usuario puede acceder a los recursos compartidos y a internet, y considera medidas para evitar que se repita. ¿Qué paso de solución de problemas es este?", ["Verificar la funcionalidad completa del sistema", "Establecer un plan de acción", "Probar la teoría para encontrar la causa", "Identificar el problema"], "Verificar la funcionalidad completa, y agregar medidas preventivas si hace falta, ocurre después de implementar la solución. Establecer un plan de acción ocurre antes de la solución, no después.", [null, "Planificar la solución ocurre antes de implementarla, no después.", "Probar la teoría se hace antes de la solución para confirmar la causa.", "Identificar el problema es el primer paso, no una verificación posterior a la solución."]],
  "x46": ["Un técnico confirma que un servidor de archivos muy utilizado necesita una actualización de firmware que requiere reinicio. Es media mañana de un día laboral. ¿Qué debe ocurrir a continuación?", ["Aplicar la actualización y reiniciar de inmediato", "Planificar la solución, evaluando el impacto y las políticas de la empresa", "Documentar los hallazgos y cerrar el ticket", "Volver a preguntar a los usuarios por los síntomas que vieron"], "Después de confirmar la teoría, el siguiente paso es un plan de acción que evalúe el impacto y siga las políticas de cambios, como programar el reinicio. Reiniciar de inmediato afectaría a todos los que usan el servidor.", ["Reiniciar un servidor muy utilizado a media mañana afectaría a todos los que lo usan.", null, "Todavía no se ha solucionado nada, así que es demasiado pronto para documentar y cerrar.", "La causa ya está confirmada; seguir preguntando no hace avanzar el proceso."]],
  "x47": ["¿Cuál es el último paso de la metodología de solución de problemas de CompTIA?", ["Verificar la funcionalidad completa del sistema", "Implementar la solución", "Documentar hallazgos, acciones y resultados", "Probar la teoría para determinar la causa"], "Documentar hallazgos, acciones y resultados es el último paso, para que otros puedan aprender de la solución. Verificar la funcionalidad viene justo antes, no al final.", ["Verificar la funcionalidad viene justo antes de la documentación, no al final.", "Implementar la solución está a la mitad del proceso.", null, "Probar la teoría es un paso temprano, mucho antes de la solución."]],
  "x48": ["Windows advierte sobre una dirección IP duplicada después de que un usuario configuró una dirección estática en su PC. La red usa DHCP. ¿Cuál es la MEJOR solución?", ["Cambiar el servidor DNS de la PC", "Reemplazar la tarjeta de red de la PC", "Acortar el tiempo de lease DHCP", "Volver a configurar la PC con DHCP"], "Volver a poner la PC en DHCP le da una dirección única del scope, lo que termina el conflicto. Acortar el lease no evita que una dirección configurada manualmente choque.", ["La configuración DNS no afecta una dirección IP duplicada.", "La NIC está bien; el problema es la dirección escrita en ella.", "Un lease más corto no evita que una dirección configurada manualmente choque.", null]],
  "x49": ["Un nuevo SSID solo de 5 GHz aparece en la mayoría de las laptops, pero una laptop antigua no lo ve en absoluto. ¿Cuál es la causa MÁS probable?", ["Su adaptador inalámbrico solo admite 2.4 GHz", "El scope DHCP se quedó sin direcciones", "La laptop tiene guardada una frase de acceso WPA3 incorrecta", "El servidor DNS de la oficina no responde"], "Un adaptador que solo admite 2.4 GHz no puede ver redes en 5 GHz. Una frase de acceso incorrecta impide que la laptop se una, pero el SSID seguiría apareciendo en la lista.", [null, "Un scope DHCP lleno impide la asignación de direcciones, pero el SSID seguiría visible.", "Una frase de acceso incorrecta impide unirse, pero el SSID seguiría en la lista.", "Los problemas de DNS no impiden que una laptop vea el nombre de una red inalámbrica."]],
  "x50": ["Una PC puede hacer ping a 8.8.8.8, pero la navegación web por nombre falla. ¿Qué herramienta debe usar el técnico para probar la resolución de nombres?", ["tracert", "nslookup", "ipconfig /release", "netstat"], "nslookup consulta directamente a los servidores DNS y muestra si los nombres se resuelven. tracert muestra la ruta hacia un host, que aquí ya funciona porque el ping por IP tiene éxito.", ["tracert muestra la ruta hacia un host, que ya funciona porque el ping por IP tiene éxito.", null, "Liberar la dirección IP rompería la conexión que funciona, no probaría el DNS.", "netstat muestra las conexiones y puertos actuales, no los resultados de la resolución de nombres."]],
  "x51": ["Un usuario reporta acceso lento al sitio de una oficina remota. El técnico quiere ver en qué salto de la ruta comienza el retraso. ¿Qué herramienta es adecuada?", ["ping", "nslookup", "tracert", "ipconfig"], "tracert enumera cada salto de router con sus tiempos de respuesta, mostrando dónde comienza el retraso. ping solo mide el viaje de ida y vuelta al host final, no cada salto.", ["ping solo mide el viaje de ida y vuelta al host final, no cada salto.", "nslookup prueba la resolución DNS, no el retraso a lo largo de la ruta.", null, "ipconfig muestra la configuración de direcciones local, no el retraso en la ruta."]],
  "x52": ["El registro de un switch muestra un puerto que se activa y desactiva repetidamente, y el usuario de ese puerto sigue perdiendo la conexión. ¿Qué debe revisar el técnico PRIMERO?", ["La configuración del servidor DNS en la PC", "La caché y las cookies del navegador", "Los drivers de impresora de la PC", "El patch cord y el enlace de la NIC"], "El flapping de un puerto suele deberse a un cable dañado, un conector flojo o una NIC que falla en la capa física. La configuración DNS afecta la búsqueda de nombres, no si el enlace se mantiene activo.", ["La configuración DNS afecta la búsqueda de nombres, no si el enlace se mantiene activo.", "La caché del navegador no puede hacer que un puerto del switch se active y desactive.", "Los drivers de impresora no tienen nada que ver con el estado del enlace de red.", null]],
  "x53": ["Las llamadas VoIP se escuchan entrecortadas. El ping muestra una latencia promedio normal, pero los tiempos de respuesta individuales varían mucho. ¿Cuál es el problema y una solución?", ["Jitter; aplicar prioridad QoS para la voz", "APIPA; renovar el lease DHCP", "Falla de DNS; vaciar la caché del resolver", "Conflicto de IP; configurar una dirección estática"], "Un retraso muy variable es jitter, que entrecorta la voz en tiempo real; QoS da prioridad al tráfico de voz. Los problemas de DNS impiden las búsquedas de nombres, pero no entrecortan una llamada ya establecida.", [null, "APIPA significaría que no hay dirección DHCP, y la llamada no funcionaría en absoluto.", "Los problemas de DNS impiden las búsquedas, pero no entrecortan una llamada en curso.", "Un conflicto de IP causa pérdida de conectividad, no un retraso variable."]],
  "x54": ["Un técnico quiere confirmar si los voltajes de salida de la PSU de una PC de escritorio están dentro de la especificación. ¿Qué herramienta es adecuada?", ["Un probador de cables", "Un multímetro", "Un conector loopback", "Una sonda de tonos"], "Un multímetro (o un probador de PSU dedicado) mide los voltajes de salida reales. Un probador de cables verifica el cableado de red, no los voltajes de la fuente de alimentación.", ["Un probador de cables verifica el cableado de red, no los voltajes de la PSU.", null, "Un conector loopback prueba el envío y la recepción de un puerto, no la salida de energía.", "Una sonda de tonos rastrea cables y no mide voltaje."]],
  "x55": ["Después de una tormenta eléctrica, una PC de escritorio no muestra ninguna luz ni movimiento de ventiladores. El tomacorriente hace funcionar bien una lámpara. ¿Qué debe hacer el técnico a continuación?", ["Reinstalar el sistema operativo", "Volver a asentar los módulos de memoria", "Probar o reemplazar la PSU", "Actualizar el firmware del BIOS"], "Con un tomacorriente que funciona y ninguna señal de energía, la PSU es la falla más probable después de una sobretensión. Volver a asentar la memoria puede corregir problemas de POST, pero los ventiladores igual girarían si hubiera energía.", ["El sistema operativo no puede cargar en una PC sin ninguna energía.", "Volver a asentar la RAM ayuda con errores de POST, pero los ventiladores igual girarían con energía.", null, "Una actualización del BIOS necesita primero un sistema que funcione y tenga energía."]],
  "x56": ["Una PC se reinicia sola durante la noche. El técnico quiere ver qué registró el sistema justo antes de cada reinicio. ¿Qué herramienta debe abrir?", ["Administrador de dispositivos", "Administración de discos", "Administrador de tareas", "Visor de eventos"], "El Visor de eventos guarda registros del sistema con marcas de tiempo, incluidos los errores previos a apagados inesperados. El Administrador de dispositivos muestra el estado del hardware y los drivers, pero no un historial de eventos.", ["El Administrador de dispositivos muestra el estado del hardware, pero no un historial de eventos.", "Administración de discos maneja particiones y volúmenes, no los registros de eventos del sistema.", "El Administrador de tareas muestra lo que se está ejecutando ahora, no lo que ocurrió durante la noche.", null]],
  "x57": ["Después de instalar una nueva tarjeta de sonido, no hay audio y el Administrador de dispositivos muestra un signo de exclamación amarillo en la tarjeta. ¿Qué debe hacer el técnico?", ["Instalar o actualizar el driver de la tarjeta", "Reemplazar las bocinas del escritorio", "Habilitar Secure Boot en UEFI", "Ejecutar CHKDSK en el disco del sistema"], "Un signo de exclamación amarillo en el Administrador de dispositivos suele indicar un driver faltante o defectuoso. Reemplazar las bocinas no eliminaría un error de dispositivo que reporta el propio Windows.", [null, "El error está en la tarjeta dentro del Administrador de dispositivos, no en las bocinas.", "Secure Boot verifica los cargadores de arranque y no causa un error del driver de una tarjeta de sonido.", "CHKDSK revisa el sistema de archivos, no los drivers de los dispositivos."]],
  "x58": ["Un monitor nuevo muestra un pequeño punto negro que permanece en el mismo lugar sin importar qué imagen se muestre. ¿Qué es esto?", ["Burn-in", "Un píxel muerto", "Resolución incorrecta", "Falla de la retroiluminación"], "Un píxel que permanece negro en cualquier imagen es un píxel muerto. El burn-in es un fantasma tenue de una imagen estática, no un solo punto oscuro.", ["El burn-in es un fantasma tenue de una imagen estática, no un solo punto negro.", null, "Una resolución incorrecta hace que toda la imagen se vea borrosa, no un solo punto.", "Una retroiluminación dañada oscurece toda la pantalla, no un solo píxel."]],
  "x59": ["Un teléfono OLED muestra un contorno tenue de la barra de navegación en todas las pantallas, incluso al ver video a pantalla completa. ¿Cuál es la causa probable?", ["Un grupo de píxeles muertos", "Un digitalizador que falla", "Burn-in por una imagen estática", "Una configuración de tasa de refresco baja"], "Los píxeles OLED envejecen de forma desigual cuando se muestra un elemento estático durante largos periodos, lo que deja una imagen fantasma permanente. Un digitalizador que falla afecta la entrada táctil, no lo que muestra la pantalla.", ["Los píxeles muertos son puntos oscuros, no el contorno de un elemento de la interfaz.", "Un digitalizador que falla afecta la entrada táctil, no la imagen mostrada.", null, "La tasa de refresco afecta la fluidez del movimiento, no las imágenes fantasma permanentes."]],
  "x60": ["Un teléfono se cayó al agua y parece seguir funcionando. ¿Cuál es la MEJOR primera acción?", ["Cargarlo por completo para revisar la batería", "Seguir usándolo normalmente mientras se seca en una bolsa de arroz", "Secar el interior con una secadora de pelo caliente", "Apagarlo de inmediato y no cargarlo"], "Apagarlo y no cargarlo reduce la probabilidad de cortocircuitos mientras el dispositivo se seca y se inspecciona. Cargar un teléfono mojado hace pasar corriente por circuitos húmedos y aumenta mucho la probabilidad de daño.", ["Cargar un teléfono mojado envía corriente por circuitos húmedos y arriesga cortocircuitos.", "Usar el teléfono mientras se seca mantiene la corriente circulando por piezas húmedas.", "El calor alto puede dañar la batería, la pantalla y los sellos.", null]],
});
